DG.put("krisnaavtaar/24",{"n":24,"title":"ਅਥ ਗੋਵਰਧਨ ਗਿਰਿ ਕਰ ਪਰ ਧਾਰਬੋ","title_roman":"Ath govardhan giri kar par dhaarbo","page":386,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":386},{"type":"verse","number":[335],"number_text":"੩੩੫।","page":386,"lines":[{"gurmukhi":"ਇਸੀ ਭਾਤਿ ਸੋ ਕ੍ਰਿਸਨ ਜੀ ਕੀਨੇ ਦਿਵਸ ਬਿਤੀਤ।","roman":"Isee bhaati so krisan jee keene divas biteet |","meaning_en":"","page":386},{"gurmukhi":"ਹਰਿ ਪੂਜਾ ਕੋ ਦਿਨੁ ਅਯੋ ਗੋਪ ਬਿਚਾਰੀ ਚੀਤਿ। ੩੩੫।","roman":"Hari poojaa ko dinu ayo gop bichaaree cheeti | 335 |","meaning_en":"","page":386}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":386},{"type":"verse","number":[336],"number_text":"੩੩੬।","page":386,"lines":[{"gurmukhi":"ਆਯੋ ਹੈ ਇੰਦ੍ਰ ਕੀ ਪੂਜਾ ਕੋ ਦ੍ਯੋਸ ਸਭੋ ਮਿਲਿ ਗੋਪਿਨ ਬਾਤ ਉਚਾਰੀ।","roman":"Aayo hai indr kee poojaa ko dyos sabho mili gopin baat uchaaree |","meaning_en":"","page":386},{"gurmukhi":"ਭੋਜਨ ਭਾਤਿ ਅਨੇਕਨ ਕੋ ਰੁ ਪੰਚਾਮ੍ਰਿਤ ਕੀ ਕਰੋ ਜਾਇ ਤਯਾਰੀ।","roman":"Bhojan bhaati anekan ko ru panchaamrit kee karo jaai tayaaree |","meaning_en":"","page":386},{"gurmukhi":"ਨੰਦ ਕਹਿਯੋ ਜਬ ਗੋਪਿਨ ਸੋ ਬਿਧਿ ਅਉਰ ਚਿਤੀ ਮਨ ਬੀਚ ਮੁਰਾਰੀ।","roman":"Nand kahiyo jab gopin so bidhi aur chitee man beech muraaree |","meaning_en":"","page":387},{"gurmukhi":"ਕੋ ਬਪੁਰਾ ਮਘਵਾ ਹਮਰੀ ਸਮ ਪੂਜਨ ਜਾਤ ਜਹਾ ਬ੍ਰਿਜ ਨਾਰੀ। ੩੩੬।","roman":"Ko bapuraa maghvaa hamree sam poojan jaat jahaa brij naaree | 336 |","meaning_en":"","page":387}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":387},{"type":"verse","number":[337],"number_text":"੩੩੭।","page":387,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਬੋਲਿਯੋ ਕਾਨ੍ਹ ਕਰੁਣਾ ਨਿਧਾਨ ਤਾਤ","roman":"Ih bidhi boliyo kaanh karunaa nidhaan taat","meaning_en":"","page":387},{"gurmukhi":"ਕਾਹੇ ਕੇ ਨਵਿਤ ਕੋ ਸਾਮ੍ਰਿਗੀ ਤੈ ਬਨਾਈ ਹੈ।","roman":"Kaahe ke navit ko saamrigee tai banaaee hai |","meaning_en":"","page":387},{"gurmukhi":"ਕਹਿਯੋ ਐਸੇ ਨੰਦ ਜੋ ਤ੍ਰਿਲੋਕੀਪਤਿ ਭਾਖੀਅਤ","roman":"Kahiyo aise nand jo trilokeepti bhaakheeat","meaning_en":"","page":387},{"gurmukhi":"ਤਾਹੀ ਕੋ ਬਨਾਈ ਹਰਿ ਕਹਿ ਕੈ ਸੁਨਾਈ ਹੈ।","roman":"Taahee ko banaaee hari kahi kai sunaaee hai |","meaning_en":"","page":387},{"gurmukhi":"ਕਾਹੇ ਕੇ ਨਵਿਤ ਕਹਿਯੋ ਬਾਰਿਦ ਤ੍ਰਿਨਨ ਕਾਜ","roman":"Kaahe ke navit kahiyo baarid trinan kaaj","meaning_en":"","page":387},{"gurmukhi":"ਗਊਅਨ ਕੀ ਰਛ ਕਰੀ ਅਉ ਹੋਤ ਆਈ ਹੈ।","roman":"Gaooan kee rachh karee au hot aaee hai |","meaning_en":"","page":387},{"gurmukhi":"ਕਹਿਯੋ ਭਗਵਾਨ ਏਤੋ ਲੋਗ ਹੈ ਅਜਾਨ ਬ੍ਰਿਜ","roman":"Kahiyo bhagvaan eto log hai ajaan brij","meaning_en":"","page":387},{"gurmukhi":"ਈਸ ਤੇ ਹੋਤ ਨਹੀ ਮਘਵਾ ਤੇ ਗਾਈ ਹੈ। ੩੩੭।","roman":"Ees te hot nahee maghvaa te gaaee hai | 337 |","meaning_en":"","page":387}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"","page":387},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":387},{"type":"verse","number":[338],"number_text":"੩੩੮।","page":387,"lines":[{"gurmukhi":"ਹੈ ਨਹੀ ਮੇਘੁ ਸੁਰਪਤਿ ਹਾਥਿ ਸੁ ਤਾਤ ਸੁਨੋ ਅਰੁ ਲੋਕ ਸਭੈ ਰੇ।","roman":"Hai nahee meghu surapti haathi su taat suno aru lok sabhai re |","meaning_en":"","page":387},{"gurmukhi":"ਭੰਜਨ ਭਉ ਅਨਭੈ ਭਗਵਾਨ ਸੁ ਦੇਤ ਸਭੈ ਜਨ ਕੋ ਅਰੁ ਲੈ ਰੇ।","roman":"Bhanjan bhau anbhai bhagvaan su det sabhai jan ko aru lai re |","meaning_en":"","page":387},{"gurmukhi":"ਕਿਉ ਮਘਵਾ ਤੁਮ ਪੂਜਨ ਜਾਤ ਕਰੋ ਤੁਮ ਸੇਵ ਹਿਤੰ ਚਿਤ ਕੈ ਰੇ।","roman":"Kiu maghvaa tum poojan jaat karo tum sev hitan chit kai re |","meaning_en":"","page":387},{"gurmukhi":"ਧ੍ਯਾਨ ਧਰੋ ਸਭ ਹੀ ਮਿਲ ਕੈ ਸਭ ਬਾਤਨ ਕੋ ਤੁਮ ਕੋ ਫਲ ਦੈ ਰੇ। ੩੩੮।","roman":"Dhyaan dharo sabh hee mil kai sabh baatan ko tum ko phal dai re | 338 |","meaning_en":"","page":387}]},{"type":"verse","number":[339],"number_text":"੩੩੯।","page":387,"lines":[{"gurmukhi":"ਬਾਸਵ ਜਗ੍ਯਨ ਕੈ ਬਸਿ ਮੇਘ ਕਿਧੋ ਬ੍ਰਹਮਾ ਇਹ ਬਾਤ ਉਚਾਰੈ।","roman":"Baasav jagyan kai basi megh kidho brahmaa ih baat uchaarai |","meaning_en":"","page":387},{"gurmukhi":"ਲੋਗਨ ਕੇ ਪ੍ਰਤਿਪਾਰਨ ਕੋ ਹਰਿ ਸੂਰਜ ਮੈ ਹੁਇ ਕੈ ਜਲ ਡਾਰੈ।","roman":"Logan ke pratipaaran ko hari sooraj mai hui kai jal daarai |","meaning_en":"","page":387},{"gurmukhi":"ਕਉਤੁਕ ਦੇਖਤ ਜੀਵਨ ਕੋ ਪਿਖਿ ਕਉਤੁਕ ਹ੍ਵੈ ਸਿਵ ਤਾਹਿ ਸੰਘਾਰੈ।","roman":"Kautuk dekhat jeevan ko pikhi kautuk hvai siv taahi sanghaarai |","meaning_en":"","page":387},{"gurmukhi":"ਹੈ ਵਹ ਏਕ ਕਿਧੋ ਸਰਤਾ ਸਮ ਬਾਹਨ ਕੇ ਜਮ ਬਾਹੇ ਬਿਥਾਰੈ। ੩੩੯।","roman":"Hai vah ek kidho sartaa sam baahan ke jam baahe bithaarai | 339 |","meaning_en":"","page":387}]},{"type":"verse","number":[340],"number_text":"੩੪੦।","page":387,"lines":[{"gurmukhi":"ਪਾਥਰ ਪੈ ਜਲ ਪੈ ਨਗ ਪੈ ਤਰ ਪੈ ਧਰ ਪੈ ਅਰੁ ਅਉਰ ਨਰੀ ਹੈ।","roman":"Paathar pai jal pai nag pai tar pai dhar pai aru aur naree hai |","meaning_en":"","page":387},{"gurmukhi":"ਦੇਵਨ ਪੈ ਅਰੁ ਦੈਤਨ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਅਉ ਮੁਰਾਰਿ ਹਰੀ ਹੈ।","roman":"Devan pai aru daitan pai kabi syaam kahai au muraari haree hai |","meaning_en":"","page":387},{"gurmukhi":"ਪਛਨ ਪੈ ਮ੍ਰਿਗਰਾਜਨ ਪੈ ਮ੍ਰਿਗ ਕੇ ਗਨ ਪੈ ਫੁਨਿ ਹੋਤ ਖਰੀ ਹੈ।","roman":"Pachhan pai mrigraajan pai mrig ke gan pai phuni hot kharee hai |","meaning_en":"","page":387},{"gurmukhi":"ਭੇਦ ਕਹਿਯੋ ਇਹ ਬਾਤ ਸਭੈ ਇਨਹੂੰ ਇਹ ਕੀ ਕਹਾ ਪੂਜ ਕਰੀ ਹੈ। ੩੪੦।","roman":"Bhed kahiyo ih baat sabhai inhoon ih kee kahaa pooj karee hai | 340 |","meaning_en":"","page":387}]},{"type":"verse","number":[341],"number_text":"੩੪੧।","page":387,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਹਸਿ ਕੈ ਹਰਿ ਬਾਤ ਕਹੀ ਨੰਦ ਪੈ ਹਮਰੀ ਬਿਨਤੀ ਸੁਨਿ ਲਈਯੈ।","roman":"Tab hee hasi kai hari baat kahee nand pai hamree bintee suni laeeyai |","meaning_en":"","page":387},{"gurmukhi":"ਪੂਜਹੁ ਬਿਪਨ ਕੋ ਮੁਖ ਗਊਅਨ ਪੂਜਨ ਜਾ ਗਿਰਿ ਹੈ ਤਹ ਜਈਯੈ।","roman":"Poojhu bipan ko mukh gaooan poojan jaa giri hai tah jaeeyai |","meaning_en":"","page":387},{"gurmukhi":"ਗਊਅਨ ਕੋ ਪਯ ਪੀਜਤ ਹੈ ਗਿਰਿ ਕੇ ਚੜ੍ਹਿਐ ਮਨਿ ਆਨੰਦ ਪਈਯੈ।","roman":"Gaooan ko pay peejat hai giri ke charhiai mani aanand paeeyai |","meaning_en":"","page":387},{"gurmukhi":"ਦਾਨ ਦਏ ਤਿਨ ਕੇ ਜਸੁ ਹ੍ਯਾ ਪਰਲੋਕ ਗਏ ਜੁ ਦਯੋ ਸੋਊ ਖਈਯੈ। ੩੪੧।","roman":"Daan dae tin ke jasu hyaa parlok gae ju dayo so'oo khaeeyai | 341 |","meaning_en":"","page":387}]},{"type":"verse","number":[342],"number_text":"੩੪੨।","page":388,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਭਗਵਾਨ ਕਹੀ ਪਿਤ ਸੋ ਇਕ ਬਾਤ ਸੁਨੋ ਤੁ ਕਹੋ ਮਮ ਤੋ ਸੋ।","roman":"Tab hee bhagvaan kahee pit so ik baat suno tu kaho mam to so |","meaning_en":"","page":388},{"gurmukhi":"ਪੂਜਹੁ ਜਾਇ ਸਬੈ ਗਿਰਿ ਕੌ ਤੁਮ ਇੰਦ੍ਰ ਕਰੈ ਕੁਪਿ ਕਿਆ ਫੁਨਿ ਤੋ ਸੋ।","roman":"Poojhu jaai sabai giri kau tum indr karai kupi kiaa phuni to so |","meaning_en":"","page":388},{"gurmukhi":"ਮੋ ਸੋ ਸੁਪੂਤ ਭਯੋ ਤੁਮਰੇ ਗ੍ਰਿਹਿ ਮਾਰਿ ਡਰੋ ਮਘਵਾ ਸੰਗਿ ਝੋਸੋ।","roman":"Mo so supoot bhayo tumre grihi maari daro maghvaa sangi jhoso |","meaning_en":"","page":388},{"gurmukhi":"ਰਹਸਿ ਕਹੀ ਪਿਤ ਪਾਰਥ ਕੀ ਤਜਿ ਹੈ ਇਹ ਜਾ ਹਮਰੀ ਅਨ ਮੋ ਸੋ। ੩੪੨।","roman":"Rahsi kahee pit paarath kee taji hai ih jaa hamree an mo so | 342 |","meaning_en":"","page":388}]},{"type":"verse","number":[343],"number_text":"੩੪੩।","page":388,"lines":[{"gurmukhi":"ਤਾਤ ਕੀ ਬਾਤ ਜੁ ਨੰਦ ਸੁਨੀ ਸਭ ਬਾਤ ਭਲੀ ਸਿਰ ਊਪਰ ਬਾਧੀ।","roman":"Taat kee baat ju nand sunee sabh baat bhalee sir oopar baadhee |","meaning_en":"","page":388},{"gurmukhi":"ਬਾਕੋ ਕੀ ਕੈ ਮੁਰਵੀ ਤਨ ਕੈ ਧਨੁ ਤੀਛਨ ਮਤ ਮਹਾ ਸਰ ਸਾਧੀ।","roman":"Baako kee kai murvee tan kai dhanu teechhan mat mahaa sar saadhee |","meaning_en":"","page":388},{"gurmukhi":"ਸ੍ਰਉਨਨ ਮੈ ਸੁਨਤਿਯੋ ਇਹ ਬਾਤ ਕਬੁਧਿ ਗੀ ਛੂਟਿ ਚਿਰੀ ਜਿਹ ਫਾਧੀ।","roman":"Sraunan mai suntiyo ih baat kabudhi gee chhooti chiree jih phaadhee |","meaning_en":"","page":388},{"gurmukhi":"ਮੋਹਿ ਕੀ ਬਾਰਿਦ ਹ੍ਵੈ ਕਰਿ ਗਿਆਨ ਨਿਵਾਰ ਦਈ ਉਮਡੀ ਜਨੁ ਆਧੀ।੩੪੩।","roman":"Mohi kee baarid hvai kari giaan nivaar daee umdee janu aadhee | 343 |","meaning_en":"","page":388}]},{"type":"verse","number":[344],"number_text":"੩੪੪।","page":388,"lines":[{"gurmukhi":"ਨੰਦ ਬੁਲਾਇ ਕੈ ਗੋਪ ਲਏ ਹਰਿ ਆਇਸੁ ਮਾਨਿ ਸਿਰ ਊਪਰ ਲੀਆ।","roman":"Nand bulaai kai gop lae hari aaisu maani sir oopar leeaa |","meaning_en":"","page":388},{"gurmukhi":"ਪੂਜਹੁ ਗਊਅਨ ਅਉ ਮੁਖ ਬਿਪਨ ਭਈਅਨ ਸੋ ਇਹ ਆਇਸੁ ਕੀਆ।","roman":"Poojhu gaooan au mukh bipan bhaeean so ih aaisu keeaa |","meaning_en":"","page":388},{"gurmukhi":"ਫੇਰਿ ਕਹਿਯੋ ਹਮ ਤਉ ਕਹਿਯੋ ਤੋ ਸੋ ਗ੍ਯਾਨ ਭਲੋ ਮਨ ਮੈ ਸਮਝੀਆ।","roman":"Pheri kahiyo ham tau kahiyo to so gyaan bhalo man mai samjheeaa |","meaning_en":"","page":388},{"gurmukhi":"ਚਿਤ ਦਯੋ ਸਭਨੋ ਹਮ ਸੋ ਤਿਹੁ ਲੋਗਨ ਕੋ ਪਤਿ ਚਿਤਨ ਕੀਆ। ੩੪੪।","roman":"Chit dayo sabhno ham so tihu logan ko pati chitan keeaa | 344 |","meaning_en":"","page":388}]},{"type":"verse","number":[345],"number_text":"੩੪੫।","page":388,"lines":[{"gurmukhi":"ਗੋਪ ਚਲੇ ਉਠ ਕੈ ਗ੍ਰਿਹ ਕੋ ਬ੍ਰਿਜ ਕੇ ਪਤਿ ਕੋ ਫੁਨਿ ਆਇਸੁ ਪਾਈ।","roman":"Gop chale uth kai grih ko brij ke pati ko phuni aaisu paaee |","meaning_en":"","page":388},{"gurmukhi":"ਅਛਤ ਧੂਪ ਪੰਚਾਮ੍ਰਿਤ ਦੀਪਕ ਪੂਜਨ ਕੀ ਸਭ ਭਾਤਿ ਬਨਾਈ।","roman":"Achhat dhoop panchaamrit deepak poojan kee sabh bhaati banaaee |","meaning_en":"","page":388},{"gurmukhi":"ਲੈ ਕੁਰਬੇ ਅਪਨੈ ਸਭ ਸੰਗਿ ਚਲੇ ਗਿਰਿ ਕੌ ਸਭ ਢੋਲ ਬਜਾਈ।","roman":"Lai kurbe apnai sabh sangi chale giri kau sabh dhol bajaaee |","meaning_en":"","page":388},{"gurmukhi":"ਨੰਦ ਚਲਿਯੋ ਜਸੁਧਾ ਊ ਚਲੀ ਭਗਵਾਨ ਚਲੇ ਮੁਸਲੀ ਸੰਗਿ ਭਾਈ। ੩੪੫।","roman":"Nand chaliyo jasudhaa oo chalee bhagvaan chale muslee sangi bhaaee | 345 |","meaning_en":"","page":388}]},{"type":"verse","number":[346],"number_text":"੩੪੬।","page":388,"lines":[{"gurmukhi":"ਨੰਦ ਚਲਿਯੋ ਕੁਰਬੇ ਸੰਗਿ ਲੈ ਕਰਿ ਤੀਰ ਜਬੈ ਗਿਰਿ ਕੇ ਚਲਿ ਆਯੋ।","roman":"Nand chaliyo kurbe sangi lai kari teer jabai giri ke chali aayo |","meaning_en":"","page":388},{"gurmukhi":"ਗਊਅਨ ਘਾਸ ਚਰਾਇਤ ਸੋ ਬਹੁ ਬਿਪਨ ਖੀਰ ਆਹਾਰ ਖਵਾਯੋ।","roman":"Gaooan ghaas charaait so bahu bipan kheer aahaar khavaayo |","meaning_en":"","page":388},{"gurmukhi":"ਆਪ ਪਰੋਸਨ ਲਾਗ ਜਦੁਪਤਿ ਗੋਪ ਸਭੈ ਮਨ ਮੈ ਸੁਖ ਪਾਯੋ।","roman":"Aap parosan laag jadupti gop sabhai man mai sukh paayo |","meaning_en":"","page":388},{"gurmukhi":"ਬਾਰ ਚੜਾਇ ਲਏ ਰਥ ਪੈ ਚਲ ਕੈ ਇਹ ਕਉਤਕ ਅਉਰ ਬਨਾਯੋ। ੩੪੬।","roman":"Baar charaai lae rath pai chal kai ih kautak aur banaayo | 346 |","meaning_en":"","page":388}]},{"type":"verse","number":[347],"number_text":"੩੪੭।","page":388,"lines":[{"gurmukhi":"ਕਉਤਕ ਏਕ ਬਿਚਾਰ ਜਦੁਪਤਿ ਸੂਰਤਿ ਏਕ ਧਰੀ ਗਿਰ ਬਾਕੀ।","roman":"Kautak ek bichaar jadupti soorti ek dharee gir baakee |","meaning_en":"","page":388},{"gurmukhi":"ਸ੍ਰਿੰਗ ਬਨਾਇ ਧਰੀ ਨਗ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜਹ ਗਮ੍ਯ ਨ ਕਾ ਕੀ।","roman":"Sring banaai dharee nag kai kabi syaam kahai jah gamy na kaa kee |","meaning_en":"","page":388},{"gurmukhi":"ਭੋਜਨ ਪਾਤ ਪ੍ਰਤਛਿ ਕਿਧੋ ਵਹ ਬਾਤ ਲਖੀ ਨ ਪਰੈ ਕਛੁ ਵਾ ਕੀ।","roman":"Bhojan paat pratchhi kidho vah baat lakhee na parai kachhu vaa kee |","meaning_en":"","page":388},{"gurmukhi":"ਕਉਤਕ ਏਕ ਲਖੈ ਭਗਵਾਨ ਅਉ ਜੋ ਪਿਖਵੈ ਅਟਕੈ ਮਤਿ ਤਾ ਕੀ। ੩੪੭।","roman":"Kautak ek lakhai bhagvaan au jo pikhvai atkai mati taa kee | 347 |","meaning_en":"","page":388}]},{"type":"verse","number":[348],"number_text":"੩੪੮।","page":389,"lines":[{"gurmukhi":"ਤੌ ਭਗਵਾਨ ਤਬੈ ਹਸਿ ਕੈ ਸਮ ਅੰਮ੍ਰਿਤ ਬਾਤ ਤਿਨੈ ਸੰਗਿ ਭਾਖੀ।","roman":"Tau bhagvaan tabai hasi kai sam anmrit baat tinai sangi bhaakhee |","meaning_en":"","page":389},{"gurmukhi":"ਭੋਜਨ ਖਾਤ ਦਯੋ ਹਮਰੋ ਗਿਰਿ ਲੋਕ ਸਭੈ ਪਿਖਵੋ ਤੁਮ ਆਖੀ।","roman":"Bhojan khaat dayo hamro giri lok sabhai pikhvo tum aakhee |","meaning_en":"","page":389},{"gurmukhi":"ਹੋਇ ਰਹੇ ਬਿਸਮੈ ਸਭ ਗੋਪ ਸੁਨੀ ਹਰਿ ਕੇ ਮੁਖ ਤੇ ਜਬ ਸਾਖੀ।","roman":"Hoi rahe bismai sabh gop sunee hari ke mukh te jab saakhee |","meaning_en":"","page":389},{"gurmukhi":"ਗਿਆਨ ਜਨਾਵਰ ਕੀ ਲਈ ਬਾਜ ਹ੍ਵੈ ਗਵਾਰਨ ਕਾਨ੍ਹ ਦਈ ਜਬ ਚਾਖੀ।੩੪੮।","roman":"Giaan janaavar kee laee baaj hvai gavaaran kaanh daee jab chaakhee | 348 |","meaning_en":"","page":389}]},{"type":"verse","number":[349],"number_text":"੩੪੯।","page":389,"lines":[{"gurmukhi":"ਅੰਜੁਲ ਜੋਰਿ ਸਭੈ ਬ੍ਰਿਜ ਕੇ ਜਨ ਕੋਟਿ ਪ੍ਰਨਾਮ ਕਰੈ ਹਰਿ ਆਗੇ।","roman":"Anjul jori sabhai brij ke jan koti pranaam karai hari aage |","meaning_en":"","page":389},{"gurmukhi":"ਭੂਲ ਗਈ ਸਭ ਕੋ ਮਘਵਾ ਸੁਧਿ ਕਾਨ੍ਹ ਹੀ ਕੇ ਰਸ ਭੀਤਰ ਪਾਗੇ।","roman":"Bhool gaee sabh ko maghvaa sudhi kaanh hee ke ras bheetar paage |","meaning_en":"","page":389},{"gurmukhi":"ਸੋਵਤ ਥੇ ਜੁ ਪਰੇ ਬਿਖ ਮੈ ਸਭ ਧ੍ਯਾਨ ਲਗੇ ਹਰਿ ਕੇ ਜਨ ਜਾਗੇ।","roman":"Sovat the ju pare bikh mai sabh dhyaan lage hari ke jan jaage |","meaning_en":"","page":389},{"gurmukhi":"ਅਉਰ ਗਈ ਸੁਧ ਭੂਲ ਸਭੋ ਇਕ ਕਾਨ੍ਹ ਹੀ ਕੇ ਰਸ ਮੈ ਅਨੁਰਾਗੇ। ੩੪੯।","roman":"Aur gaee sudh bhool sabho ik kaanh hee ke ras mai anuraage | 349 |","meaning_en":"","page":389}]},{"type":"verse","number":[350],"number_text":"੩੫੦।","page":389,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਸਭ ਕੋ ਹਸਿ ਕੇ ਮਿਲਿ ਧਾਮਿ ਚਲੋ ਜੋਊ ਹੈ ਹਰਤਾ ਅਘ।","roman":"Kaanh kahee sabh ko hasi ke mili dhaami chalo jo'oo hai hartaa agh |","meaning_en":"","page":389},{"gurmukhi":"ਨੰਦ ਚਲਿਯੋ ਬਲਭਦ੍ਰ ਚਲਿਯੋ ਜਸੁਧਾ ਊ ਚਲੀ ਨੰਦ ਲਾਲ ਬਿਨਾਨਘ।","roman":"Nand chaliyo balbhadr chaliyo jasudhaa oo chalee nand laal binaanagh |","meaning_en":"","page":389},{"gurmukhi":"ਪੂਜ ਜਬੈ ਇਨਹੂੰ ਨ ਕਰੀ ਤਬ ਹੀ ਕੁਪਿਓ ਇਨ ਪੈ ਧਰਤਾ ਪ੍ਰਘ।","roman":"Pooj jabai inhoon na karee tab hee kupio in pai dhartaa pragh |","meaning_en":"","page":389},{"gurmukhi":"ਬੇਦਨ ਮਧ ਕਹੀ ਇਨਿ ਭੀਮ ਤੇ ਮਾਰਿ ਡਰਿਯੋ ਛਲ ਸੋ ਪਤਵਾ ਮਘ। ੩੫੦।","roman":"Bedan madh kahee ini bheem te maari dariyo chhal so patvaa magh | 350 |","meaning_en":"","page":389}]},{"type":"verse","number":[351],"number_text":"੩੫੧।","page":389,"lines":[{"gurmukhi":"ਭੂ ਸੁਤ ਸੋ ਲਰ ਕੈ ਜਿਨ ਹੂੰ ਨਵਸਾਤ ਛੁਡਾਇ ਲਈ ਬਰਮੰਙਾ।","roman":"Bhoo sut so lar kai jin hoon navsaat chhudaai laee barmanngaa |","meaning_en":"","page":389},{"gurmukhi":"ਆਦਿ ਸਤਜੁਗ ਕੇ ਮੁਰ ਕੇ ਗੜ ਤੋਰਿ ਦਏ ਸਭ ਜਿਉ ਕਚ ਬੰਙਾ।","roman":"Aadi satjug ke mur ke gar tori dae sabh jiu kach banngaa |","meaning_en":"","page":389},{"gurmukhi":"ਹੈ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੋ ਅਰੁ ਦੇਵਨ ਹਾਰ ਇਹੀ ਜੁਗ ਸੰਙਾ।","roman":"Hai kartaa sabh hee jag ko aru devan haar ihee jug sanngaa |","meaning_en":"","page":389},{"gurmukhi":"ਲੋਕਨ ਕੋ ਪਤਿ ਸੋ ਮਤਿ ਮੰਦ ਬਿਬਾਦ ਕਰੈ ਮਘਵਾ ਮਤਿ ਲੰਙਾ। ੩੫੧।","roman":"Lokan ko pati so mati mand bibaad karai maghvaa mati lanngaa | 351 |","meaning_en":"","page":389}]},{"type":"verse","number":[352],"number_text":"੩੫੨।","page":389,"lines":[{"gurmukhi":"ਗੋਪਨ ਸੋ ਖਿਝ ਕੈ ਮਘਵਾ ਤਜਿ ਕੈ ਮਨਿ ਆਨੰਦ ਕੋਪ ਰਚੇ।","roman":"Gopan so khijh kai maghvaa taji kai mani aanand kop rache |","meaning_en":"","page":389},{"gurmukhi":"ਸੰਗਿ ਮੇਘਨ ਜਾਇ ਕਹੀ ਬਰਖੋ ਬ੍ਰਿਜ ਪੈ ਰਸ ਬੀਰ ਹੀ ਮਧ ਗਚੇ।","roman":"Sangi meghan jaai kahee barkho brij pai ras beer hee madh gache |","meaning_en":"","page":389},{"gurmukhi":"ਕਰੀਯੋ ਬਰਖਾ ਇਤਨੀ ਉਨ ਪੈ ਜਿਹ ਤੇ ਫੁਨਿ ਗੋਪ ਨ ਏਕ ਬਚੇ।","roman":"Kareeyo barkhaa itnee un pai jih te phuni gop na ek bache |","meaning_en":"","page":389},{"gurmukhi":"ਸਭ ਭੈਨਨ ਭ੍ਰਾਤਨ ਤਾਤਨ ਪਊਤ੍ਰਨ ਤਊਅਨ ਮਾਰਹੁ ਸਾਥ ਚਚੇ। ੩੫੨।","roman":"Sabh bhainan bhraatan taatan paootran taooan maarhu saath chache | 352 |","meaning_en":"","page":389}]},{"type":"verse","number":[353],"number_text":"੩੫੩।","page":389,"lines":[{"gurmukhi":"ਆਇਸੁ ਮਾਨਿ ਪੁਰੰਦਰ ਕੋ ਅਪਨੇ ਸਭ ਮੇਘਨ ਕਾਛ ਸੁ ਕਾਛੇ।","roman":"Aaisu maani purandar ko apne sabh meghan kaachh su kaachhe |","meaning_en":"","page":389},{"gurmukhi":"ਧਾਇ ਚਲੇ ਬ੍ਰਿਜ ਕੇ ਮਰਬੇ ਕਹੁ ਘੇਰਿ ਦਸੋ ਦਿਸ ਤੇ ਘਨ ਆਛੇ।","roman":"Dhaai chale brij ke marbe kahu gheri daso dis te ghan aachhe |","meaning_en":"","page":389},{"gurmukhi":"ਕੋਪ ਭਰੇ ਅਰੁ ਬਾਰਿ ਭਰੇ ਬਧਬੇ ਕਉ ਚਲੇ ਚਰੀਆ ਜੋਊ ਬਾਛੇ।","roman":"Kop bhare aru baari bhare badhbe kau chale chareeaa jo'oo baachhe |","meaning_en":"","page":389},{"gurmukhi":"ਛਿਪ੍ਰ ਚਲੇ ਕਰਬੇ ਨ੍ਰਿਪ ਕਾਰਜ ਛੋਡਿ ਚਲੇ ਬਨਿਤਾ ਸੁਤ ਪਾਛੇ। ੩੫੩।","roman":"Chhipr chale karbe nrip kaaraj chhodi chale banitaa sut paachhe | 353 |","meaning_en":"","page":389}]},{"type":"verse","number":[354],"number_text":"੩੫੪।","page":389,"lines":[{"gurmukhi":"ਦੈਤ ਸੰਖਾਸੁਰ ਕੇ ਮਰਬੇ ਕਹੁ ਰੂਪੁ ਧਰਿਯੋ ਜਲ ਮੈ ਜਿਨਿ ਮਛਾ।","roman":"Dait sankhaasur ke marbe kahu roopu dhariyo jal mai jini machhaa |","meaning_en":"","page":389},{"gurmukhi":"ਸਿੰਧੁ ਮਥਿਯੋ ਜਬ ਹੀ ਅਸੁਰਾਸੁਰ ਮੇਰੁ ਤਰੈ ਭਯੋ ਕਛਪ ਹਛਾ।","roman":"Sindhu mathiyo jab hee asuraasur meru tarai bhayo kachhap hachhaa |","meaning_en":"","page":389},{"gurmukhi":"ਸੋ ਅਬ ਕਾਨ੍ਹ ਭਯੋ ਇਹ ਠਉਰਿ ਚਰਾਵਤ ਹੈ ਬ੍ਰਿਜ ਕੇ ਸਭ ਬਛਾ।","roman":"So ab kaanh bhayo ih thauri charaavat hai brij ke sabh bachhaa |","meaning_en":"","page":389},{"gurmukhi":"ਖੇਲ ਦਿਖਾਵਤ ਹੈ ਜਗ ਕੋ ਇਹ ਹੈ ਕਰਤਾ ਸਭ ਜੀਵਨ ਰਛਾ। ੩੫੪।","roman":"Khel dikhaavat hai jag ko ih hai kartaa sabh jeevan rachhaa | 354 |","meaning_en":"","page":389}]},{"type":"verse","number":[355],"number_text":"੩੫੫।","page":390,"lines":[{"gurmukhi":"ਆਇਸ ਮਾਨਿ ਸਭੈ ਮਘਵਾ ਹਰਿ ਕੇ ਪੁਰ ਘੇਰਿ ਘਨੇ ਘਨ ਗਾਜੈ।","roman":"Aais maani sabhai maghvaa hari ke pur gheri ghane ghan gaajai |","meaning_en":"","page":390},{"gurmukhi":"ਦਾਮਿਨਿ ਜਿਉ ਗਰਜੈ ਜਨੁ ਰਾਮ ਕੇ ਸਾਮੁਹਿ ਰਾਵਨ ਦੁੰਦਭਿ ਬਾਜੈ।","roman":"Daamini jiu garjai janu raam ke saamuhi raavan dundbhi baajai |","meaning_en":"","page":390},{"gurmukhi":"ਸੋ ਧੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਸੁਨਿ ਗੋਪ ਦਸੋ ਦਿਸ ਕੋ ਡਰ ਕੈ ਉਠਿ ਭਾਜੈ।","roman":"So dhuni sraunan mai suni gop daso dis ko dar kai uthi bhaajai |","meaning_en":"","page":390},{"gurmukhi":"ਆਇ ਪਰੇ ਹਰਿ ਕੇ ਸਭ ਪਾਇਨ ਆਪਨ ਜੀਵ ਸਹਾਇਕ ਕਾਜੈ। ੩੫੫।","roman":"Aai pare hari ke sabh paain aapan jeev sahaaik kaajai | 355 |","meaning_en":"","page":390}]},{"type":"verse","number":[356],"number_text":"੩੫੬।","page":390,"lines":[{"gurmukhi":"ਮੇਘਨ ਕੋ ਡਰ ਕੈ ਹਰਿ ਸਾਮੁਹਿ ਗੋਪ ਪੁਕਾਰਤ ਹੈ ਦੁਖੁ ਮਾਝਾ।","roman":"Meghan ko dar kai hari saamuhi gop pukaarat hai dukhu maajhaa |","meaning_en":"","page":390},{"gurmukhi":"ਰਛ ਕਰੋ ਹਮਰੀ ਕਰੁਨਾਨਿਧਿ ਬ੍ਰਿਸਟ ਭਈ ਦਿਨ ਅਉ ਸਤ ਸਾਝਾ।","roman":"Rachh karo hamree karunaanidhi brisat bhaee din au sat saajhaa |","meaning_en":"","page":390},{"gurmukhi":"ਏਕ ਬਚੀ ਨ ਗਊ ਪੁਰ ਕੀ ਮਰਗੀ ਦੁਧਰੀ ਬਛਰੇ ਅਰੁ ਬਾਝਾ।","roman":"Ek bachee na gaoo pur kee margee dudhree bachhre aru baajhaa |","meaning_en":"","page":390},{"gurmukhi":"ਅਗ੍ਰਜ ਸ੍ਯਾਮ ਕੇ ਰੋਵਤ ਇਉ ਜਿਮ ਹੀਰ ਬਿਨਾ ਪਿਖਏ ਪਤਿ ਰਾਝਾ।੩੫੬।","roman":"Agraj syaam ke rovat iu jim heer binaa pikhae pati raajhaa | 356 |","meaning_en":"","page":390}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":390},{"type":"verse","number":[357],"number_text":"੩੫੭।","page":390,"lines":[{"gurmukhi":"ਕਾਲੀ ਨਾਥ ਕੇਸੀ ਰਿਪੁ ਕਉਲ ਨੈਨ ਕਉਲ ਨਾਭਿ","roman":"Kaalee naath kesee ripu kaul nain kaul naabhi","meaning_en":"","page":390},{"gurmukhi":"ਕਮਲਾ ਕੇ ਪਤਿ ਇਹ ਬਿਨਤੀ ਸੁਨੀਜੀਯੈ।","roman":"Kamlaa ke pati ih bintee suneejeeyai |","meaning_en":"","page":390},{"gurmukhi":"ਕਾਮ ਰੂਪ ਕੰਸ ਕੇ ਪ੍ਰਹਾਰੀ ਕਾਜਕਾਰੀ ਪ੍ਰਭ","roman":"Kaam roop kans ke prahaaree kaajkaaree prabh","meaning_en":"","page":390},{"gurmukhi":"ਕਾਮਿਨੀ ਕੇ ਕਾਮ ਕੇ ਨਿਵਾਰੀ ਕਾਮ ਕੀਜੀਯੈ।","roman":"Kaaminee ke kaam ke nivaaree kaam keejeeyai |","meaning_en":"","page":390},{"gurmukhi":"ਕਉਲਾਸਨ ਪਤਿ ਕੁੰਭਕਾਨ ਕੇ ਮਰਈਯਾ","roman":"Kaulaasan pati kunbhkaan ke maraeeyaa","meaning_en":"","page":390},{"gurmukhi":"ਕਾਲਨੇਮਿ ਕੇ ਬਧਈਯਾ ਐਸੀ ਕੀਜੈ ਜਾ ਤੇ ਜੀਜੀਯੈ।","roman":"Kaalnemi ke badhaeeyaa aisee keejai jaa te jeejeeyai |","meaning_en":"","page":390},{"gurmukhi":"ਕਾਰਮਾ ਹਰਨ ਕਾਜ ਸਾਧਨ ਕਰਤ ਤੁਮ","roman":"Kaarmaa haran kaaj saadhan karat tum","meaning_en":"","page":390},{"gurmukhi":"ਕ੍ਰਿਪਾ ਨਿਧਿ ਦਾਸਨ ਅਰਜ ਸੁਨਿ ਲੀਜੀਯੈ। ੩੫੭।","roman":"Kripaa nidhi daasan araj suni leejeeyai | 357 |","meaning_en":"","page":390}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":390},{"type":"verse","number":[358],"number_text":"੩੫੮।","page":390,"lines":[{"gurmukhi":"ਬੂੰਦਨ ਤੀਰਨ ਸੀ ਸਭ ਹੀ ਕੁਪ ਕੈ ਬ੍ਰਿਜ ਕੇ ਪੁਰ ਪੈ ਜਬ ਪਈਯਾ।","roman":"Boondan teeran see sabh hee kup kai brij ke pur pai jab paeeyaa |","meaning_en":"","page":390},{"gurmukhi":"ਸੋਊ ਸਹੀ ਨ ਗਈ ਕਿਹ ਪੈ ਸਭ ਧਾਮਨ ਬੇਧਿ ਧਰਾ ਲਗਿ ਗਈਯਾ।","roman":"So'oo sahee na gaee kih pai sabh dhaaman bedhi dharaa lagi gaeeyaa |","meaning_en":"","page":390},{"gurmukhi":"ਸੋ ਪਿਖਿ ਗੋਪਨ ਨੈਨਨ ਸੋ ਬਿਨਤੀ ਹਰਿ ਕੇ ਅਗੂਆ ਪਹੁਚਈਯਾ।","roman":"So pikhi gopan nainan so bintee hari ke agooaa pahuchaeeyaa |","meaning_en":"","page":390},{"gurmukhi":"ਕੋਪ ਭਰਿਯੋ ਹਮ ਪੈ ਮਘਵਾ ਹਮਰੀ ਤੁਮ ਰਛ ਕਰੋ ਉਠਿ ਸਈਯਾ। ੩੫੮।","roman":"Kop bhariyo ham pai maghvaa hamree tum rachh karo uthi saeeyaa | 358 |","meaning_en":"","page":390}]},{"type":"verse","number":[359],"number_text":"੩੫੯।","page":390,"lines":[{"gurmukhi":"ਦੀਸਤ ਹੈ ਨ ਕਹੂੰ ਅਰਣੋਦਿਤ ਘੇਰਿ ਦਸੋ ਦਿਸ ਤੇ ਘਨ ਆਵੈ।","roman":"Deesat hai na kahoon arnodit gheri daso dis te ghan aavai |","meaning_en":"","page":390},{"gurmukhi":"ਕੋਪ ਭਰੇ ਜਨੁ ਕੇਹਰਿ ਗਾਜਤ ਦਾਮਿਨਿ ਦਾਤ ਨਿਕਾਸਿ ਡਰਾਵੈ।","roman":"Kop bhare janu kehri gaajat daamini daat nikaasi daraavai |","meaning_en":"","page":390},{"gurmukhi":"ਗੋਪਨ ਜਾਇ ਕਰੀ ਬਿਨਤੀ ਹਰਿ ਪੈ ਸੁਨੀਯੈ ਹਰਿ ਜੋ ਤੁਮ ਭਾਵੈ।","roman":"Gopan jaai karee bintee hari pai suneeyai hari jo tum bhaavai |","meaning_en":"","page":390},{"gurmukhi":"ਸਿੰਘ ਕੇ ਦੇਖਤ ਸਿੰਘਨ ਸ੍ਯਾਰ ਕਹੈ ਕੁਪ ਕੈ ਜਮ ਲੋਕ ਪਠਾਵੈ। ੩੫੯।","roman":"Singh ke dekhat singhan syaar kahai kup kai jam lok pathaavai | 359 |","meaning_en":"","page":390}]},{"type":"verse","number":[360],"number_text":"੩੬੦।","page":390,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਹਮਰੇ ਪੁਰ ਮੈ ਬਹੁ ਮੇਘਨ ਕੇ ਇਹ ਠਾਟ ਠਟੇ।","roman":"Kop bhare hamre pur mai bahu meghan ke ih thaat thate |","meaning_en":"","page":390},{"gurmukhi":"ਜਿਹ ਕੋ ਗਜ ਬਾਹਨ ਲੋਕ ਕਹੈ ਜਿਨਿ ਪਬਨ ਕੇ ਪਰ ਕੋਪ ਕਟੇ।","roman":"Jih ko gaj baahan lok kahai jini paban ke par kop kate |","meaning_en":"","page":390},{"gurmukhi":"ਤੁਮ ਹੋ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੇ ਤੁਮ ਹੀ ਸਿਰ ਰਾਵਨ ਕਾਟਿ ਸਟੇ।","roman":"Tum ho kartaa sabh hee jag ke tum hee sir raavan kaati sate |","meaning_en":"","page":391},{"gurmukhi":"ਤੁਮ ਸਿਯੋ ਫੁਨਿ ਦੇਖਿਤ ਗੋਪਨ ਕੋ ਘਨ ਘੋਰਿ ਡਰਾਵਤ ਕੋਪ ਲਟੇ। ੩੬੦।","roman":"Tum siyo phuni dekhit gopan ko ghan ghori daraavat kop late | 360 |","meaning_en":"","page":391}]},{"type":"verse","number":[361],"number_text":"੩੬੧।","page":391,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਡੋ ਸੁਨਿ ਲੋਕ ਤੁਮੈ ਫੁਨਿ ਜਾਮ ਸੁ ਜਾਪ ਕਰੈ ਤੁਹ ਆਠੋ।","roman":"Kaanh bado suni lok tumai phuni jaam su jaap karai tuh aatho |","meaning_en":"","page":391},{"gurmukhi":"ਨੀਰ ਹੁਤਾਸਨ ਭੂਮਿ ਧਰਾਧਰ ਥਾਪਿ ਕਰਿਯੋ ਤੁਮ ਹੀ ਪ੍ਰਭ ਕਾਠੋ।","roman":"Neer hutaasan bhoomi dharaadhar thaapi kariyo tum hee prabh kaatho |","meaning_en":"","page":391},{"gurmukhi":"ਬੇਦ ਦਏ ਕਰ ਕੈ ਤੁਮ ਹੀ ਜਗ ਮੈ ਛਿਨ ਤਾਤ ਭਯੋ ਜਬ ਘਾਠੋ।","roman":"Bed dae kar kai tum hee jag mai chhin taat bhayo jab ghaatho |","meaning_en":"","page":391},{"gurmukhi":"ਸਿੰਧੁ ਮਥਿਯੋ ਤੁਮ ਹੀ ਤ੍ਰੀਯ ਹ੍ਵੈ ਕਰਿ ਦੀਨ ਸੁਰਾਸੁਰ ਅਮ੍ਰਿਤ ਬਾਟੋ। ੩੬੧।","roman":"Sindhu mathiyo tum hee treey hvai kari deen suraasur amrit baato | 361 |","meaning_en":"","page":391}]},{"type":"verse","number":[362],"number_text":"੩੬੨।","page":391,"lines":[{"gurmukhi":"ਗੋਪਨ ਫੇਰਿ ਕਹੀ ਮੁਖਤੇ ਬਿਨੁ ਤੈ ਹਮਰੋ ਕੋਊ ਅਉਰ ਨ ਆਡਾ।","roman":"Gopan pheri kahee mukhte binu tai hamro ko'oo aur na aadaa |","meaning_en":"","page":391},{"gurmukhi":"ਮੇਘਨ ਮਾਰਿ ਬਿਥਾਰ ਡਰੋ ਕੁਪਿ ਬਾਲਕ ਮੂਰਤਿ ਜਿਉ ਤੁਮ ਗਾਡਾ।","roman":"Meghan maari bithaar daro kupi baalak moorti jiu tum gaadaa |","meaning_en":"","page":391},{"gurmukhi":"ਮੇਘਨ ਕੋ ਪਿਖਿ ਰੂਪ ਭਯਾਨਕ ਬਹੁਤੁ ਡਰੈ ਫੁਨਿ ਜੀਉ ਅਸਾਡਾ।","roman":"Meghan ko pikhi roop bhayaanak bahutu darai phuni jeeu asaadaa |","meaning_en":"","page":391},{"gurmukhi":"ਕਾਨ੍ਹ ਅਬੈ ਪੁਸਤੀਨ ਹ੍ਵੈ ਆਪ ਉਤਾਰ ਡਰੋ ਸਭ ਗੋਪਨ ਜਾਡਾ। ੩੬੨।","roman":"Kaanh abai pusteen hvai aap utaar daro sabh gopan jaadaa | 362 |","meaning_en":"","page":391}]},{"type":"verse","number":[363],"number_text":"੩੬੩।","page":391,"lines":[{"gurmukhi":"ਆਇਸੁ ਪਾਇ ਪੁਰੰਦਰ ਕੋ ਘਨਘੋਰ ਘਟਾ ਚਹੂੰ ਓਰ ਤੇ ਆਵੈ।","roman":"Aaisu paai purandar ko ghanghor ghataa chahoon or te aavai |","meaning_en":"","page":391},{"gurmukhi":"ਕੈ ਕਰ ਕ੍ਰੁਧ ਕਿਧੋ ਮਨ ਮਧਿ ਬ੍ਰਿਜ ਊਪਰ ਆਨ ਕੈ ਬਹੁ ਬਲ ਪਾਵੈ।","roman":"Kai kar krudh kidho man madhi brij oopar aan kai bahu bal paavai |","meaning_en":"","page":391},{"gurmukhi":"ਅਉ ਅਤਿ ਹੀ ਚਪਲਾ ਚਮਕੈ ਬਹੁ ਬੂੰਦਨ ਤੀਰਨ ਸੀ ਬਰਖਾਵੈ।","roman":"Au ati hee chaplaa chamkai bahu boondan teeran see barkhaavai |","meaning_en":"","page":391},{"gurmukhi":"ਗੋਪ ਕਹੈ ਹਮ ਤੇ ਭਈ ਚੂਕ ਸੁ ਯਾ ਤੇ ਹਮੈ ਗਰਜੈ ਔ ਡਰਾਵੈ। ੩੬੩।","roman":"Gop kahai ham te bhaee chook su yaa te hamai garjai au daraavai | 363 |","meaning_en":"","page":391}]},{"type":"verse","number":[364],"number_text":"੩੬੪।","page":391,"lines":[{"gurmukhi":"ਆਜ ਭਯੋ ਉਤਪਾਤ ਬਡੋ ਡਰੁ ਸਮਾਨਿ ਸਭੈ ਹਰਿ ਪਾਸ ਪੁਕਾਰੇ।","roman":"Aaj bhayo utpaat bado daru samaani sabhai hari paas pukaare |","meaning_en":"","page":391},{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਹਮ ਪੈ ਮਘਵਾ ਤਿਹ ਤੇ ਬ੍ਰਿਜ ਪੈ ਬਰਖੇ ਘਨ ਭਾਰੇ।","roman":"Kop kariyo ham pai maghvaa tih te brij pai barkhe ghan bhaare |","meaning_en":"","page":391},{"gurmukhi":"ਭਛਿ ਭਖਿਯੋ ਇਹ ਕੋ ਤੁਮ ਹੂ ਤਿਹ ਤੇ ਬ੍ਰਿਜ ਕੇ ਜਨ ਕੋਪਿ ਸੰਘਾਰੇ।","roman":"Bhachhi bhakhiyo ih ko tum hoo tih te brij ke jan kopi sanghaare |","meaning_en":"","page":391},{"gurmukhi":"ਰਛਕ ਹੋ ਸਭ ਹੀ ਜਗ ਕੇ ਤੁਮ ਰਛ ਕਰੋ ਹਮਰੀ ਰਖਵਾਰੇ। ੩੬੪।","roman":"Rachhak ho sabh hee jag ke tum rachh karo hamree rakhvaare | 364 |","meaning_en":"","page":391}]},{"type":"verse","number":[365],"number_text":"੩੬੫।","page":391,"lines":[{"gurmukhi":"ਹੋਇ ਕ੍ਰਿਪਾਲ ਅਬੈ ਭਗਵਾਨ ਕ੍ਰਿਪਾ ਕਰਿ ਕੈ ਇਨ ਕੋ ਤੁਮ ਕਾਢੋ।","roman":"Hoi kripaal abai bhagvaan kripaa kari kai in ko tum kaadho |","meaning_en":"","page":391},{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਹਮ ਪੈ ਮਘਵਾ ਦਿਨ ਸਾਤ ਇਹਾ ਬਰਖਿਯੋ ਘਨ ਗਾਢੋ।","roman":"Kop kariyo ham pai maghvaa din saat ihaa barkhiyo ghan gaadho |","meaning_en":"","page":391},{"gurmukhi":"ਭ੍ਰਾਤ ਬਲੀ ਇਨਿ ਰਛਨ ਕੋ ਤਬ ਹੀ ਕਰਿ ਕੋਪ ਭਯੋ ਉਠਿ ਠਾਢੋ।","roman":"Bhraat balee ini rachhan ko tab hee kari kop bhayo uthi thaadho |","meaning_en":"","page":391},{"gurmukhi":"ਜੀਵ ਗਯੋ ਘਟ ਮੇਘਨ ਕੋ ਸਭ ਗੋਪਨ ਕੇ ਮਨ ਆਨੰਦ ਬਾਢੋ। ੩੬੫।","roman":"Jeev gayo ghat meghan ko sabh gopan ke man aanand baadho | 365 |","meaning_en":"","page":391}]},{"type":"verse","number":[366],"number_text":"੩੬੬।","page":391,"lines":[{"gurmukhi":"ਗੋਪਨ ਕੀ ਸੁਨ ਕੈ ਬਿਨਤੀ ਹਰਿ ਗੋਪ ਸਭੈ ਅਪਨੇ ਕਰਿ ਜਾਣੇ।","roman":"Gopan kee sun kai bintee hari gop sabhai apne kari jaane |","meaning_en":"","page":391},{"gurmukhi":"ਮੇਘਨ ਕੇ ਬਧਬੇ ਕਹੁ ਕਾਨ੍ਹ ਚਲਿਯੋ ਉਠਿ ਕੈ ਕਰਤਾ ਜੋਊ ਤਾਣੇ।","roman":"Meghan ke badhbe kahu kaanh chaliyo uthi kai kartaa jo'oo taane |","meaning_en":"","page":391},{"gurmukhi":"ਤਾ ਛਬਿ ਕੇ ਜਸ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਅਪਨੇ ਮਨ ਮੈ ਪਹਿਚਾਣੇ।","roman":"Taa chhabi ke jas uch mahaa kabi ne apne man mai pahichaane |","meaning_en":"","page":391},{"gurmukhi":"ਇਉ ਚਲ ਗਯੋ ਜਿਮ ਸਿੰਘ ਮ੍ਰਿਗੀ ਪਿਖਿ ਆਇ ਹੈ ਜਾਨ ਕਿਧੋ ਮੂਹਿ ਡਾਣੇ। ੩੬੬।","roman":"Iu chal gayo jim singh mrigee pikhi aai hai jaan kidho moohi daane | 366 |","meaning_en":"","page":391}]},{"type":"verse","number":[367],"number_text":"੩੬੭।","page":392,"lines":[{"gurmukhi":"ਮੇਘਨ ਕੇ ਬਧ ਕਾਜ ਚਲਿਯੋ ਭਗਵਾਨ ਕਿਧੋ ਰਸ ਭੀਤਰ ਰਤਾ।","roman":"Meghan ke badh kaaj chaliyo bhagvaan kidho ras bheetar rataa |","meaning_en":"","page":392},{"gurmukhi":"ਰਾਮ ਭਯੋ ਜੁਗ ਤੀਸਰ ਮਧਿ ਮਰਿਯੋ ਤਿਨ ਰਾਵਨ ਕੈ ਰਨ ਅਤਾ।","roman":"Raam bhayo jug teesar madhi mariyo tin raavan kai ran ataa |","meaning_en":"","page":392},{"gurmukhi":"ਅਉਧ ਕੇ ਬੀਚ ਬਧੂ ਬਰਬੇ ਕਹੁ ਕੋਪ ਕੈ ਬੈਲ ਨਥੇ ਜਿਹ ਸਤਾ।","roman":"Audh ke beech badhoo barbe kahu kop kai bail nathe jih sataa |","meaning_en":"","page":392},{"gurmukhi":"ਗੋਪਨ ਗੋਧਨ ਰਛਨ ਕਾਜ ਤੁਰਿਯੋ ਤਿਹ ਕੋ ਗਜ ਜਿਉ ਮਦ ਮਤਾ। ੩੬੭।","roman":"Gopan godhan rachhan kaaj turiyo tih ko gaj jiu mad mataa | 367 |","meaning_en":"","page":392}]},{"type":"verse","number":[368],"number_text":"੩੬੮।","page":392,"lines":[{"gurmukhi":"ਕਰਬੇ ਕਹੁ ਰਛ ਸੁ ਗੋਪਨ ਕੀ ਬਰ ਪੂਟ ਲਯੋ ਨਗ ਕੋ ਪਹਿ ਹਥਾ।","roman":"Karbe kahu rachh su gopan kee bar poot layo nag ko pahi hathaa |","meaning_en":"","page":392},{"gurmukhi":"ਤਨ ਕੋ ਨ ਕਰਿਯੋ ਬਲ ਰੰਚਕ ਤਾਹ ਕਰਿਯੋ ਜੁ ਹੁਤੋ ਕਰ ਬੀਚ ਜਥਾ।","roman":"Tan ko na kariyo bal ranchak taah kariyo ju huto kar beech jathaa |","meaning_en":"","page":392},{"gurmukhi":"ਨ ਚਲੀ ਤਿਨ ਕੀ ਕਿਛੁ ਗੋਪਨ ਪੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਗਜ ਜਾਹਿ ਰਥਾ।","roman":"Na chalee tin kee kichhu gopan pai kabi syaam kahai gaj jaahi rathaa |","meaning_en":"","page":392},{"gurmukhi":"ਮੁਖਿ ਨ੍ਯਾਇ ਖਿਸਾਇ ਚਲਿਯੋ ਗ੍ਰਿਹ ਪੈ ਇਹ ਬੀਚ ਚਲੀ ਜਗ ਕੇ ਸੁ ਕਥਾ।੩੬੮।","roman":"Mukhi nyaai khisaai chaliyo grih pai ih beech chalee jag ke su kathaa | 368 |","meaning_en":"","page":392}]},{"type":"verse","number":[369],"number_text":"੩੬੯।","page":392,"lines":[{"gurmukhi":"ਨੰਦ ਕੋ ਨੰਦ ਬਡੋ ਸੁਖ ਕੰਦ ਰਿਪੁ ਆਰ ਸੁਰੰਦ ਸਬੁਧਿ ਬਿਸਾਰਦ।","roman":"Nand ko nand bado sukh kand ripu aar surand sabudhi bisaarad |","meaning_en":"","page":392},{"gurmukhi":"ਆਨਨ ਚੰਦ ਪ੍ਰਭਾ ਕਹੁ ਮੰਦ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਜਪੈ ਜਿਹ ਨਾਰਦ।","roman":"Aanan chand prabhaa kahu mand kahai kabi syaam japai jih naarad |","meaning_en":"","page":392},{"gurmukhi":"ਤਾ ਗਿਰਿ ਕੋਪ ਉਠਾਇ ਲਯੋ ਜੋਊ ਸਾਧਨ ਕੋ ਹਰਤਾ ਦੁਖ ਦਾਰਦ।","roman":"Taa giri kop uthaai layo jo'oo saadhan ko hartaa dukh daarad |","meaning_en":"","page":392},{"gurmukhi":"ਮੇਘ ਪਰੇ ਉਪਰਿਯੋ ਨ ਕਛੂ ਪਛਤਾਇ ਗਏ ਗ੍ਰਿਹ ਕੋ ਉਠਿ ਬਾਰਦ। ੩੬੯।","roman":"Megh pare upriyo na kachhoo pachhtaai gae grih ko uthi baarad | 369 |","meaning_en":"","page":392}]},{"type":"verse","number":[370],"number_text":"੩੭੦।","page":392,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਉਪਾਰਿ ਲਯੋ ਕਰ ਮੋ ਗਿਰਿ ਏਕ ਪਰੀ ਨਹੀ ਬੂੰਦ ਸੁ ਪਾਨੀ।","roman":"Kaanh upaari layo kar mo giri ek paree nahee boond su paanee |","meaning_en":"","page":392},{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਹਸਿ ਕੈ ਮੁਖ ਤੇ ਹਰਿ ਕੋ ਮਘਵਾ ਜੁ ਭਯੋ ਮੁਹਿ ਸਾਨੀ।","roman":"Pheri kahee hasi kai mukh te hari ko maghvaa ju bhayo muhi saanee |","meaning_en":"","page":392},{"gurmukhi":"ਮਾਰਿ ਡਰਿਯੋ ਮੁਰ ਮੈ ਮਧੁ ਕੀਟਭ ਮਾਰਿਯੋ ਹਮੈ ਮਘਵਾ ਪਤਿ ਮਾਨੀ।","roman":"Maari dariyo mur mai madhu keetabh maariyo hamai maghvaa pati maanee |","meaning_en":"","page":392},{"gurmukhi":"ਗੋਪਨ ਮੈ ਭਗਵਾਨ ਕਹੀ ਸੋਊ ਫੈਲ ਪਰੀ ਜਗ ਬੀਚ ਕਹਾਨੀ। ੩੭੦।","roman":"Gopan mai bhagvaan kahee so'oo phail paree jag beech kahaanee | 370 |","meaning_en":"","page":392}]},{"type":"verse","number":[371],"number_text":"੩੭੧।","page":392,"lines":[{"gurmukhi":"ਗੋਪਨ ਕੀ ਕਰਬੇ ਕਹੁ ਰਛ ਸਤਕ੍ਰਿਤ ਪੈ ਹਰਿ ਜੀ ਜਬ ਕੋਪੇ।","roman":"Gopan kee karbe kahu rachh satkrit pai hari jee jab kope |","meaning_en":"","page":392},{"gurmukhi":"ਇਉ ਗਿਰਿ ਕੇ ਤਰਿ ਭਯੋ ਉਠਿ ਠਾਢਿ ਮਨੋ ਰੁਪ ਕੈ ਪਗ ਕੇਹਰਿ ਰੋਪੇ।","roman":"Iu giri ke tari bhayo uthi thaadhi mano rup kai pag kehri rope |","meaning_en":"","page":392},{"gurmukhi":"ਜਿਉ ਜੁਗ ਅੰਤ ਮੈ ਅੰਤਕ ਹ੍ਵੈ ਕਰਿ ਜੀਵਨ ਕੇ ਸਭ ਕੇ ਉਰਿ ਘੋਪੇ।","roman":"Jiu jug ant mai antak hvai kari jeevan ke sabh ke uri ghope |","meaning_en":"","page":392},{"gurmukhi":"ਜਿਉ ਜਨ ਕੋ ਮਨ ਹੋਤ ਹੈ ਲੋਪ ਤਿਸੀ ਬਿਧਿ ਮੇਘ ਭਏ ਸਭ ਲੋਪੇ। ੩੭੧।","roman":"Jiu jan ko man hot hai lop tisee bidhi megh bhae sabh lope | 371 |","meaning_en":"","page":392}]},{"type":"verse","number":[372],"number_text":"੩੭੨।","page":392,"lines":[{"gurmukhi":"ਹੋਇ ਸਤਕ੍ਰਿਤ ਊਪਰ ਕੋਪ ਸੁ ਰਾਖ ਲਈ ਸਭ ਗੋਪ ਦਫਾ।","roman":"Hoi satkrit oopar kop su raakh laee sabh gop daphaa |","meaning_en":"","page":392},{"gurmukhi":"ਤਿਨਿ ਮੇਘ ਬਿਦਾਰ ਦਏ ਛਿਨ ਮੈ ਜਿਨਿ ਦੈਤ ਕਰੇ ਸਭ ਏਕ ਗਫਾ।","roman":"Tini megh bidaar dae chhin mai jini dait kare sabh ek gaphaa |","meaning_en":"","page":392},{"gurmukhi":"ਕਰਿ ਕਉਤੁਕ ਪੈ ਰਿਪੁ ਟਾਰ ਦਏ ਬਿਨੁ ਹੀ ਧਰਏ ਸਰ ਸ੍ਯਾਮ ਜਫਾ।","roman":"Kari kautuk pai ripu taar dae binu hee dharae sar syaam japhaa |","meaning_en":"","page":392},{"gurmukhi":"ਸਭ ਗੋਪਨ ਕੀ ਕਰਬੈ ਕਹੁ ਰਛ ਸੁ ਸਕ੍ਰਨ ਲੀਨ ਲਪੇਟ ਸਫਾ। ੩੭੨।","roman":"Sabh gopan kee karbai kahu rachh su sakran leen lapet saphaa | 372 |","meaning_en":"","page":392}]},{"type":"verse","number":[373],"number_text":"੩੭੩।","page":392,"lines":[{"gurmukhi":"ਜੁ ਲਈ ਸਭ ਮੇਘ ਲਪੇਟ ਸਫਾ ਅਰੁ ਲੀਨੋ ਹੈ ਪਬ ਉਪਾਰ ਜਬੈ।","roman":"Ju laee sabh megh lapet saphaa aru leeno hai pab upaar jabai |","meaning_en":"","page":392},{"gurmukhi":"ਇਹ ਰੰਚਕ ਸੋ ਇਹ ਹੈ ਗਰੂਓ ਗਿਰਿ ਚਿੰਤ ਕਰੀ ਮਨਿ ਬੀਚ ਸਬੈ।","roman":"Ih ranchak so ih hai garoo'o giri chint karee mani beech sabai |","meaning_en":"","page":392},{"gurmukhi":"ਇਹ ਦੈਤਨ ਕੋ ਮਰਤਾ ਕਰਤਾ ਸੁਖ ਹੈ ਦਿਵਿਯਾ ਜੀਯ ਦਾਨ ਅਬੈ।","roman":"Ih daitan ko martaa kartaa sukh hai diviyaa jeey daan abai |","meaning_en":"","page":393},{"gurmukhi":"ਇਹ ਕੋ ਤੁਮ ਧ੍ਯਾਨ ਧਰੋ ਸਭ ਹੀ ਨਹਿ ਧ੍ਯਾਨ ਧਰੋ ਤੁਮ ਅਉਰ ਕਬੈ।੩੭੩।","roman":"Ih ko tum dhyaan dharo sabh hee nahi dhyaan dharo tum aur kabai | 373 |","meaning_en":"","page":393}]},{"type":"verse","number":[374],"number_text":"੩੭੪।","page":393,"lines":[{"gurmukhi":"ਸਭ ਮੇਘ ਗਏ ਘਟ ਕੇ ਜਬ ਹੀ ਤਬ ਹੀ ਹਰਖੇ ਫੁਨਿ ਗੋਪ ਸਭੈ।","roman":"Sabh megh gae ghat ke jab hee tab hee harkhe phuni gop sabhai |","meaning_en":"","page":393},{"gurmukhi":"ਇਹ ਭਾਤਿ ਲਗੇ ਕਹਨੇ ਮੁਖ ਤੇ ਭਗਵਾਨ ਦਯੋ ਹਮ ਦਾਨ ਅਭੈ।","roman":"Ih bhaati lage kahne mukh te bhagvaan dayo ham daan abhai |","meaning_en":"","page":393},{"gurmukhi":"ਮਘਵਾ ਜੁ ਕਰੀ ਕੁਪਿ ਦਉਰ ਹਮੂ ਪਰ ਸੋ ਤਿਹ ਕੋ ਨਹੀ ਬੇਰ ਲਭੈ।","roman":"Maghvaa ju karee kupi daur hamoo par so tih ko nahee ber labhai |","meaning_en":"","page":393},{"gurmukhi":"ਅਬ ਕਾਨ੍ਹ ਪ੍ਰਤਾਪ ਤੇ ਹੈ ਘਟ ਬਾਦਰ ਏਕ ਨ ਦੀਸਤ ਬੀਚ ਨਭੈ। ੩੭੪।","roman":"Ab kaanh prataap te hai ghat baadar ek na deesat beech nabhai | 374 |","meaning_en":"","page":393}]},{"type":"verse","number":[375],"number_text":"੩੭੫।","page":393,"lines":[{"gurmukhi":"ਗੋਪ ਕਹੈ ਸਭ ਹੀ ਮੁਖ ਤੇ ਇਹ ਕਾਨ੍ਹ ਬਲੀ ਬਰ ਹੈ ਬਲ ਮੈ।","roman":"Gop kahai sabh hee mukh te ih kaanh balee bar hai bal mai |","meaning_en":"","page":393},{"gurmukhi":"ਜਿਨਿ ਕੂਦਿ ਕਿਲੇ ਸਤ ਮੋਰ ਮਰਿਯੋ ਜਿਨਿ ਜੁਧ ਸੰਖਾਸੁਰ ਸੋ ਜਲ ਮੈ।","roman":"Jini koodi kile sat mor mariyo jini judh sankhaasur so jal mai |","meaning_en":"","page":393},{"gurmukhi":"ਇਹ ਹੈ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੋ ਅਰੁ ਫੈਲ ਰਹਿਯੋ ਜਲ ਅਉ ਥਲ ਮੈ।","roman":"Ih hai kartaa sabh hee jag ko aru phail rahiyo jal au thal mai |","meaning_en":"","page":393},{"gurmukhi":"ਸੋਊ ਆਇ ਪ੍ਰਤਛਿ ਭਯੋ ਬ੍ਰਿਜ ਮੈ ਜੋਊ ਜੋਗ ਜੁਤੋ ਰਹੈ ਓਝਲ ਮੈ। ੩੭੫।","roman":"So'oo aai pratchhi bhayo brij mai jo'oo jog juto rahai ojhal mai | 375 |","meaning_en":"","page":393}]},{"type":"verse","number":[376],"number_text":"੩੭੬।","page":393,"lines":[{"gurmukhi":"ਮੋਰ ਮਰਿਯੋ ਜਿਨਿ ਕੂਦ ਕਿਲੈ ਸਤ ਸੰਧਿ ਜਰਾ ਜਿਹ ਸੈਨ ਮਰੀ।","roman":"Mor mariyo jini kood kilai sat sandhi jaraa jih sain maree |","meaning_en":"","page":393},{"gurmukhi":"ਨਰਾਕਸੁਰ ਜਾਹਿ ਕਰਿਯੋ ਰਕਸੀ ਬਿਰਥੀ ਗਜ ਕੀ ਜਿਹ ਰਛ ਕਰੀ।","roman":"Naraaksur jaahi kariyo raksee birthee gaj kee jih rachh karee |","meaning_en":"","page":393},{"gurmukhi":"ਜਿਹ ਰਾਖਿ ਲਈ ਪਤਿ ਪੈ ਦ੍ਰੁਪਤੀ ਸਿਲ ਜਾ ਲਗਤਿਉ ਪਗ ਪਾਰਿ ਪਰੀ।","roman":"Jih raakhi laee pati pai druptee sil jaa lagtiu pag paari paree |","meaning_en":"","page":393,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਅਤਿ ਕੋਪਤ ਮੇਘਨ ਅਉ ਮਘਵਾ ਇਹ ਰਾਖ ਲਈ ਨੰਦ ਲਾਲਿ ਧਰੀ।੩੭੬।","roman":"Ati kopat meghan au maghvaa ih raakh laee nand laali dharee | 376 |","meaning_en":"","page":393}]},{"type":"verse","number":[377],"number_text":"੩੭੭।","page":393,"lines":[{"gurmukhi":"ਮਘਵਾ ਜਿਹ ਫੇਰਿ ਦਈ ਪ੍ਰਤਨਾ ਜਿਹ ਦੈਤੁ ਮਰੇ ਇਹ ਕਾਨ ਬਲੀ।","roman":"Maghvaa jih pheri daee pratnaa jih daitu mare ih kaan balee |","meaning_en":"","page":393},{"gurmukhi":"ਜਿਹ ਕੋ ਜਨ ਨਾਮ ਜਪੈ ਮਨ ਮੈ ਜਿਹ ਕੋ ਫੁਨਿ ਭ੍ਰਾਤ ਹੈ ਬੀਰ ਹਲੀ।","roman":"Jih ko jan naam japai man mai jih ko phuni bhraat hai beer halee |","meaning_en":"","page":393},{"gurmukhi":"ਜਿਹ ਤੇ ਸਭ ਗੋਪਨ ਕੀ ਬਿਪਤਾ ਹਰਿ ਕੇ ਕੁਪ ਤੇ ਛਿਨ ਮਾਹਿ ਟਲੀ।","roman":"Jih te sabh gopan kee biptaa hari ke kup te chhin maahi talee |","meaning_en":"","page":393},{"gurmukhi":"ਤਿਹ ਕੋ ਲਖ ਕੈ ਉਪਮਾ ਭਗਵਾਨ ਕਰੈ ਜਿਹ ਕੀ ਸੁਤ ਕਉਲ ਕਲੀ।੩੭੭।","roman":"Tih ko lakh kai upmaa bhagvaan karai jih kee sut kaul kalee | 377 |","meaning_en":"","page":393}]},{"type":"verse","number":[378],"number_text":"੩੭੮।","page":393,"lines":[{"gurmukhi":"ਕਾਨ ਉਪਾਰ ਲਯੋ ਗਰੂਓ ਗਿਰਿ ਧਾਮਿ ਖਿਸਾਇ ਗਯੋ ਮਘਵਾ।","roman":"Kaan upaar layo garoo'o giri dhaami khisaai gayo maghvaa |","meaning_en":"","page":393},{"gurmukhi":"ਸੋ ਉਪਜਿਯੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਜੋਊ ਤੀਸਰ ਜੁਗ ਭਯੋ ਰਘੁਵਾ।","roman":"So upjiyo brij bhoomi bikhai jo'oo teesar jug bhayo raghuvaa |","meaning_en":"","page":393},{"gurmukhi":"ਅਬ ਕਉਤੁਕਿ ਲੋਕ ਦਿਖਾਵਨ ਕੋ ਜਗ ਮੈ ਫੁਨਿ ਰੂਪ ਧਰਿਯੋ ਲਘੁਵਾ।","roman":"Ab kautuki lok dikhaavan ko jag mai phuni roop dhariyo laghuvaa |","meaning_en":"","page":393},{"gurmukhi":"ਥਨ ਐਚ ਹਨੀ ਛਿਨ ਮੈ ਪੁਤਨਾ ਹਰਿ ਨਾਮ ਕੇ ਲੇਤ ਹਰੇ ਅਘਵਾ। ੩੭੮।","roman":"Than aich hanee chhin mai putnaa hari naam ke let hare aghvaa | 378 |","meaning_en":"","page":393}]},{"type":"verse","number":[379],"number_text":"੩੭੯।","page":393,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਲੀ ਪ੍ਰਗਟਿਯੋ ਬ੍ਰਿਜ ਮੈ ਜਿਨਿ ਗੋਪਨ ਕੇ ਦੁਖ ਕਾਟਿ ਸਟੇ।","roman":"Kaanh balee pragtiyo brij mai jini gopan ke dukh kaati sate |","meaning_en":"","page":393},{"gurmukhi":"ਸੁਖ ਸਾਧਨ ਕੇ ਪ੍ਰਗਟੇ ਤਬ ਹੀ ਦੁਖ ਦੈਤਨ ਕੇ ਸੁਨਿ ਨਾਮੁ ਘਟੇ।","roman":"Sukh saadhan ke pragte tab hee dukh daitan ke suni naamu ghate |","meaning_en":"","page":393},{"gurmukhi":"ਇਹ ਹੈ ਕਰਤਾ ਸਭ ਹੀ ਜਗ ਕੋ ਬਲਿ ਕੋ ਅਰੁ ਇੰਦ੍ਰਹਿ ਲੋਕ ਬਟੇ।","roman":"Ih hai kartaa sabh hee jag ko bali ko aru indrahi lok bate |","meaning_en":"","page":393},{"gurmukhi":"ਤਿਹ ਨਾਮ ਕੇ ਲੇਤ ਕਿਧੋ ਮੁਖ ਤੇ ਲਟ ਜਾਤ ਸਭੈ ਤਨ ਦੋਖ ਲਟੇ। ੩੭੯।","roman":"Tih naam ke let kidho mukh te lat jaat sabhai tan dokh late | 379 |","meaning_en":"","page":393}]},{"type":"verse","number":[380],"number_text":"੩੮੦।","page":394,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਲੀ ਪ੍ਰਗਟਿਯੋ ਪੁਤਨਾ ਜਿਨਿ ਮਾਰਿ ਡਰੀ ਨ੍ਰਿਪ ਕੰਸ ਪਠੀ।","roman":"Kaanh balee pragtiyo putnaa jini maari daree nrip kans pathee |","meaning_en":"","page":394},{"gurmukhi":"ਇਨ ਹੀ ਰਿਪੁ ਮਾਰਿ ਡਰਿਯੋ ਸੁ ਤ੍ਰਿਨਾਵ੍ਰਤ ਪੈ ਜਨਿ ਸੋ ਇਹ ਥਿਤ ਛਠੀ।","roman":"In hee ripu maari dariyo su trinaavrat pai jani so ih thit chhathee |","meaning_en":"","page":394},{"gurmukhi":"ਸਭ ਜਾਪੁ ਜਪੈ ਇਹ ਕੋ ਮਨ ਮੈ ਸਭ ਗੋਪ ਕਹੈ ਇਹ ਅਤਿ ਹਠੀ।","roman":"Sabh jaapu japai ih ko man mai sabh gop kahai ih ati hathee |","meaning_en":"","page":394},{"gurmukhi":"ਅਤਿ ਹੀ ਪ੍ਰਤਿਨਾ ਫੁਨਿ ਮੇਘਨ ਕੀ ਇਨਹੂ ਕਰਿ ਦੀ ਛਿਨ ਮਾਹਿ ਮਠੀ।੩੮੦।","roman":"Ati hee pratinaa phuni meghan kee inhoo kari dee chhin maahi mathee | 380 |","meaning_en":"","page":394}]},{"type":"verse","number":[381],"number_text":"੩੮੧।","page":394,"lines":[{"gurmukhi":"ਗੋਪ ਕਹੈ ਇਹ ਸਾਧਨ ਕੇ ਦੁਖ ਦੂਰਿ ਕਰੈ ਮਨ ਮਾਹਿ ਗਡੈ।","roman":"Gop kahai ih saadhan ke dukh doori karai man maahi gadai |","meaning_en":"","page":394},{"gurmukhi":"ਇਹ ਹੈ ਬਲਵਾਨ ਬਡੋ ਪ੍ਰਗਟਿਯੋ ਸੋਊ ਕੋ ਇਹ ਸੋ ਛਿਨ ਆਇ ਅਡੈ।","roman":"Ih hai balvaan bado pragtiyo so'oo ko ih so chhin aai adai |","meaning_en":"","page":394},{"gurmukhi":"ਸਭ ਲੋਕ ਕਹੈ ਫੁਨਿ ਜਾਪਤ ਯਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਭਗਵਾਨ ਬਡੈ।","roman":"Sabh lok kahai phuni jaapat yaa kabi syaam kahai bhagvaan badai |","meaning_en":"","page":394},{"gurmukhi":"ਤਿਨ ਮੋਛ ਲਹੀ ਛਿਨ ਮੈ ਇਹ ਤੇ ਜਿਨ ਕੇ ਮਨ ਮੈ ਜਰਰਾ ਕੁ ਜਡੈ। ੩੮੧।","roman":"Tin mochh lahee chhin mai ih te jin ke man mai jarraa ku jadai | 381 |","meaning_en":"","page":394}]},{"type":"verse","number":[382],"number_text":"੩੮੨।","page":394,"lines":[{"gurmukhi":"ਮੇਘ ਗਏ ਪਛੁਤਾਇ ਗ੍ਰਿਹੰ ਕਹੁ ਗੋਪਿਨ ਕੋ ਮਨ ਆਨੰਦ ਬਾਢੇ।","roman":"Megh gae pachhutaai grihan kahu gopin ko man aanand baadhe |","meaning_en":"","page":394},{"gurmukhi":"ਹ੍ਵੈ ਇਕਠੇ ਸੁ ਚਲੇ ਗ੍ਰਿਹ ਕੋ ਸਭ ਆਇ ਭਏ ਗ੍ਰਿਹ ਭੀਤਰ ਠਾਢੇ।","roman":"Hvai ikthe su chale grih ko sabh aai bhae grih bheetar thaadhe |","meaning_en":"","page":394},{"gurmukhi":"ਆਇ ਲਗੇ ਕਹਿਨੇ ਤ੍ਰੀਯ ਸੋ ਇਨ ਹੀ ਛਿਨ ਮੈ ਮਘਵਾ ਕੁਪਿ ਕਾਢੇ।","roman":"Aai lage kahine treey so in hee chhin mai maghvaa kupi kaadhe |","meaning_en":"","page":394},{"gurmukhi":"ਸਤਿ ਲਹਿਯੋ ਭਗਵਾਨ ਹਮੈ ਇਨ ਹੀ ਹਮਰੇ ਸਭ ਹੀ ਦੁਖ ਕਾਢੇ। ੩੮੨।","roman":"Sati lahiyo bhagvaan hamai in hee hamre sabh hee dukh kaadhe | 382 |","meaning_en":"","page":394}]},{"type":"verse","number":[383],"number_text":"੩੮੩।","page":394,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਪਤਿ ਲੋਕਹ ਕੇ ਦਲ ਆਬ ਰਖੇ ਠਟਿ ਸਾਜ ਅਣੇ।","roman":"Kop bhare pati lokah ke dal aab rakhe thati saaj ane |","meaning_en":"","page":394},{"gurmukhi":"ਭਗਵਾਨ ਜੂ ਠਾਢ ਭਯੋ ਕਰਿ ਲੈ ਗਿਰਿ ਪੈ ਕਰਿ ਕੈ ਕੁਛ ਹੂੰ ਨ ਗਣੇ।","roman":"Bhagvaan joo thaadh bhayo kari lai giri pai kari kai kuchh hoon na gane |","meaning_en":"","page":394},{"gurmukhi":"ਅਤਿ ਤਾ ਛਬਿ ਕੇ ਜਸ ਉਚ ਮਹਾ ਕਬਿ ਸ੍ਯਾਮ ਕਿਧੌ ਇਹ ਭਾਤਿ ਭਣੇ।","roman":"Ati taa chhabi ke jas uch mahaa kabi syaam kidhau ih bhaati bhane |","meaning_en":"","page":394},{"gurmukhi":"ਜਿਮੁ ਬੀਰ ਬਡੋ ਕਰਿ ਸਿਪਰ ਲੈ ਕਛੁ ਕੈ ਨ ਗਨੇ ਪੁਨਿ ਤੀਰ ਘਣੇ। ੩੮੩।","roman":"Jimu beer bado kari sipar lai kachhu kai na gane puni teer ghane | 383 |","meaning_en":"","page":394}]},{"type":"verse","number":[384],"number_text":"੩੮੪।","page":394,"lines":[{"gurmukhi":"ਗੋਪ ਕਹੈ ਇਹ ਸਾਧਨ ਕੋ ਦੁਖ ਦੂਰ ਕਰੈ ਮਨ ਮਾਹਿ ਗਡੈ।","roman":"Gop kahai ih saadhan ko dukh door karai man maahi gadai |","meaning_en":"","page":394},{"gurmukhi":"ਇਹ ਹੈ ਬਲਵਾਨ ਬਡੋ ਪ੍ਰਗਟਿਓ ਸੋਊ ਕੋ ਇਹ ਸੋ ਛਿਨ ਆਇ ਅਡੈ।","roman":"Ih hai balvaan bado pragtio so'oo ko ih so chhin aai adai |","meaning_en":"","page":394},{"gurmukhi":"ਸਭ ਲੋਗ ਕਹੈ ਫੁਨਿ ਖਾਪਤ ਯਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਭਗਵਾਨ ਬਡੈ।","roman":"Sabh log kahai phuni khaapat yaa kabi syaam kahai bhagvaan badai |","meaning_en":"","page":394},{"gurmukhi":"ਤਿਹ ਮੋਛ ਲਹੀ ਛਿਨ ਮੈ ਇਹ ਤੇ ਜਿਨ ਕੇ ਮਨ ਮੈ ਜਰਰਾ ਕੁ ਜਡੈ। ੩੮੪।","roman":"Tih mochh lahee chhin mai ih te jin ke man mai jarraa ku jadai | 384 |","meaning_en":"","page":394}]},{"type":"verse","number":[385],"number_text":"੩੮੫।","page":394,"lines":[{"gurmukhi":"ਕਰਿ ਕੋਪ ਨਿਵਾਰ ਦਏ ਮਘਵਾ ਦਲ ਕਾਨ ਬਡੇ ਬਲਬੀਰ ਬ੍ਰਤੀ।","roman":"Kari kop nivaar dae maghvaa dal kaan bade balbeer bratee |","meaning_en":"","page":394},{"gurmukhi":"ਜਿਮ ਕੋਪਿ ਜਲੰਧਰਿ ਈਸਿ ਮਰਿਯੋ ਜਿਮ ਚੰਡਿ ਚਮੁੰਡਹਿ ਸੈਨ ਹਤੀ।","roman":"Jim kopi jalandhri eesi mariyo jim chandi chamundhi sain hatee |","meaning_en":"","page":394},{"gurmukhi":"ਪਛੁਤਾਇ ਗਯੋ ਮਘਵਾ ਗ੍ਰਿਹ ਕੋ ਨ ਰਹੀ ਤਿਹ ਕੀ ਪਤਿ ਏਕ ਰਤੀ।","roman":"Pachhutaai gayo maghvaa grih ko na rahee tih kee pati ek ratee |","meaning_en":"","page":394},{"gurmukhi":"ਇਕ ਮੇਘ ਬਿਦਾਰ ਦਏ ਹਰਿ ਜੀ ਜਿਮ ਮੋਹਿ ਨਿਵਾਰਤ ਕੋਪਿ ਜਤੀ। ੩੮੫।","roman":"Ik megh bidaar dae hari jee jim mohi nivaarat kopi jatee | 385 |","meaning_en":"","page":394}]},{"type":"verse","number":[386],"number_text":"੩੮੬।","page":395,"lines":[{"gurmukhi":"ਕੁਪ ਕੈ ਤਿਨਿ ਮੇਘ ਬਿਦਾਰ ਦਏ ਜਿਨਿ ਰਾਖ ਲਯੋ ਜਲ ਭੀਤਰ ਹਾਥੀ।","roman":"Kup kai tini megh bidaar dae jini raakh layo jal bheetar haathee |","meaning_en":"","page":395},{"gurmukhi":"ਜਾਹਿ ਸਿਲਾ ਲਗਿ ਪਾਇ ਤਰੀ ਜਿਹ ਰਾਖਿ ਲਈ ਦ੍ਰੁਪਤੀ ਸੁ ਅਨਾਥੀ।","roman":"Jaahi silaa lagi paai taree jih raakhi laee druptee su anaathee |","meaning_en":"","page":395},{"gurmukhi":"ਬੈਰ ਕਰੈ ਜੋਊ ਪੈ ਇਹ ਸੋ ਸਭ ਗੋਪ ਕਹੈ ਇਹ ਤਾਹਿ ਅਸਾਥੀ।","roman":"Bair karai jo'oo pai ih so sabh gop kahai ih taahi asaathee |","meaning_en":"","page":395},{"gurmukhi":"ਜੋ ਹਿਤ ਸੋ ਚਿਤ ਕੈ ਇਹ ਕੀ ਫੁਨਿ ਸੇਵ ਕਰੈ ਤਿਹ ਕੋ ਇਹ ਸਾਥੀ। ੩੮੬।","roman":"Jo hit so chit kai ih kee phuni sev karai tih ko ih saathee | 386 |","meaning_en":"","page":395}]},{"type":"verse","number":[387],"number_text":"੩੮੭।","page":395,"lines":[{"gurmukhi":"ਮੇਘਨ ਕੋ ਤਬ ਹੀ ਕ੍ਰਿਸਨੰ ਦਲ ਖਾਤਿਰ ਊਪਰਿ ਨ ਕਛੂ ਆਂਦਾ।","roman":"Meghan ko tab hee krisnan dal khaatir oopri na kachhoo aandaa |","meaning_en":"","page":395},{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਅਤਿ ਹੀ ਮਘਵਾ ਨ ਚਲਿਯੋ ਤਿਹ ਸੋ ਕਛੁ ਤਾਹਿ ਬਸਾਂਦਾ।","roman":"Kop kariyo ati hee maghvaa na chaliyo tih so kachhu taahi basaandaa |","meaning_en":"","page":395},{"gurmukhi":"ਜੋਰ ਚਲੈ ਕਿਹ ਕੋ ਤਿਹ ਸੋ ਕਹਿ ਹੈ ਸਭ ਹੀ ਜਿਸ ਕੋ ਜਗੁ ਬਾਂਦਾ।","roman":"Jor chalai kih ko tih so kahi hai sabh hee jis ko jagu baandaa |","meaning_en":"","page":395},{"gurmukhi":"ਮੂੰਡ ਨਿਵਾਇ ਮਨੈ ਦੁਖ ਪਾਇ ਗਯੋ ਮਘਵਾ ਉਠਿ ਧਾਮਿ ਖਿਸਾਂਦਾ। ੩੮੭।","roman":"Moond nivaai manai dukh paai gayo maghvaa uthi dhaami khisaandaa | 387 |","meaning_en":"","page":395}]},{"type":"verse","number":[388],"number_text":"੩੮੮।","page":395,"lines":[{"gurmukhi":"ਸਕ੍ਰ ਗਯੋ ਪਛੁਤਾਹਿ ਗ੍ਰਿਹੰ ਕਹੁ ਫੋਰ ਦਈ ਜਬ ਕਾਨ੍ਹਿ ਅਨੀ।","roman":"Sakr gayo pachhutaahi grihan kahu phor daee jab kaanhi anee |","meaning_en":"","page":395},{"gurmukhi":"ਬਰਖਾ ਕਰਿ ਕੋਪ ਕਰੀ ਬ੍ਰਿਜ ਪੈ ਸੁ ਕਛੂ ਹਰਿ ਕੈ ਨਹਿ ਏਕ ਗਨੀ।","roman":"Barkhaa kari kop karee brij pai su kachhoo hari kai nahi ek ganee |","meaning_en":"","page":395},{"gurmukhi":"ਫੁਨਿ ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਸ੍ਯਾਮ ਕਿਧੋ ਇਹ ਭਾਤਿ ਭਨੀ।","roman":"Phuni taa chhabi kee ati hee upmaa kabi syaam kidho ih bhaati bhanee |","meaning_en":"","page":395},{"gurmukhi":"ਪਛਤਾਇ ਗਯੋ ਪਤਿ ਲੋਕਨ ਕੋ ਜਿਮ ਲੂਟ ਲਯੋ ਅਹਿ ਸੀਸ ਮਨੀ। ੩੮੮।","roman":"Pachhtaai gayo pati lokan ko jim loot layo ahi sees manee | 388 |","meaning_en":"","page":395}]},{"type":"verse","number":[389],"number_text":"੩੮੯।","page":395,"lines":[{"gurmukhi":"ਜਾਹਿ ਨ ਜਾਨਤ ਭੇਦ ਮੁਨੀ ਮਨਿ ਭਾ ਇਹ ਜਾਪਨ ਕੋ ਇਹ ਜਾਪੀ।","roman":"Jaahi na jaanat bhed munee mani bhaa ih jaapan ko ih jaapee |","meaning_en":"","page":395},{"gurmukhi":"ਰਾਜ ਦਯੋ ਇਨ ਹੀ ਬਲਿ ਕੋ ਇਨ ਹੀ ਕਬਿ ਸ੍ਯਾਮ ਧਰਾ ਸਭ ਥਾਪੀ।","roman":"Raaj dayo in hee bali ko in hee kabi syaam dharaa sabh thaapee |","meaning_en":"","page":395},{"gurmukhi":"ਮਾਰਤ ਹੈ ਦਿਨ ਥੋਰਨ ਮੈ ਰਿਪੁ ਗੋਪ ਕਹੈ ਇਹ ਕਾਨ ਪ੍ਰਤਾਪੀ।","roman":"Maarat hai din thoran mai ripu gop kahai ih kaan prataapee |","meaning_en":"","page":395},{"gurmukhi":"ਕਾਰਨ ਯਾਹਿ ਧਰੀ ਇਹ ਮੂਰਤਿ ਮਾਰਨ ਕੋ ਜਗ ਕੇ ਸਭ ਪਾਪੀ। ੩੮੯।","roman":"Kaaran yaahi dharee ih moorti maaran ko jag ke sabh paapee | 389 |","meaning_en":"","page":395}]},{"type":"verse","number":[390],"number_text":"੩੯੦।","page":395,"lines":[{"gurmukhi":"ਕਰਿ ਕੈ ਜਿਹ ਸੋ ਛਲ ਪੈ ਚਤੁਰਾਨਨ ਚੋਰਿ ਲਏ ਸਭ ਗੋਪ ਦਫਾ।","roman":"Kari kai jih so chhal pai chaturaanan chori lae sabh gop daphaa |","meaning_en":"","page":395},{"gurmukhi":"ਤਿਨ ਕਉਤਕ ਦੇਖਨ ਕਾਰਨ ਕੋ ਫੁਨਿ ਰਾਖਿ ਰਹਿਓ ਵਹ ਬੀਚ ਖਫਾ।","roman":"Tin kautak dekhan kaaran ko phuni raakhi rahio vah beech khaphaa |","meaning_en":"","page":395},{"gurmukhi":"ਕਾਨ ਬਿਨਾ ਕੁਪਏ ਉਹ ਸੋ ਸੁ ਕਰੇ ਬਿਨ ਹੀ ਸਰ ਦੀਨ ਜਫਾ।","roman":"Kaan binaa kupae uh so su kare bin hee sar deen japhaa |","meaning_en":"","page":395},{"gurmukhi":"ਛਿਨ ਮਧਿ ਬਨਾਇ ਲਏ ਬਛਰੇ ਸਭ ਗੋਪਨ ਕੀ ਉਨ ਹੀ ਸੀ ਸਫਾ। ੩੯੦।","roman":"Chhin madhi banaai lae bachhre sabh gopan kee un hee see saphaa | 390 |","meaning_en":"","page":395}]},{"type":"verse","number":[391],"number_text":"੩੯੧।","page":395,"lines":[{"gurmukhi":"ਕਾਨ ਉਪਾਰਿ ਧਰਿਓ ਕਰ ਪੈ ਗਿਰਿ ਤਾ ਤਰਿ ਗੋਪ ਨਿਕਾਰਿ ਸਬੈ।","roman":"Kaan upaari dhario kar pai giri taa tari gop nikaari sabai |","meaning_en":"","page":395},{"gurmukhi":"ਬਕਈ ਬਕ ਅਉਰ ਗਡਾਸੁਰ ਤ੍ਰਿਨਾਵ੍ਰਤ ਬੀਰ ਬਧੇ ਛਿਨ ਬੀਚ ਤਬੈ।","roman":"Bakaee bak aur gadaasur trinaavrat beer badhe chhin beech tabai |","meaning_en":"","page":395},{"gurmukhi":"ਜਿਨ ਕਾਲੀ ਕੋ ਨਾਥ ਲਯੋ ਛਿਨ ਭੀਤਰ ਧਿਆਨ ਨ ਛਾਡਹੁ ਵਾਹਿ ਕਬੈ।","roman":"Jin kaalee ko naath layo chhin bheetar dhiaan na chhaadhu vaahi kabai |","meaning_en":"","page":395},{"gurmukhi":"ਸਭ ਸੰਤ ਸੁਨੀ ਸੁਭ ਕਾਨ੍ਹ ਕਥਾ ਇਕ ਅਉਰ ਕਥਾ ਸੁਨਿ ਲੇਹੁ ਅਬੈ। ੩੯੧।","roman":"Sabh sant sunee subh kaanh kathaa ik aur kathaa suni lehu abai | 391 |","meaning_en":"","page":395}]},{"type":"heading","kind":"speaker","name":"ਗੋਪ ਬਾਚ ਨੰਦ ਜੂ ਸੋ","gurmukhi":"ਗੋਪ ਬਾਚ ਨੰਦ ਜੂ ਸੋ","roman":"Gop baach nand joo so","meaning_en":"","page":396},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":396},{"type":"verse","number":[392],"number_text":"੩੯੨।","page":396,"lines":[{"gurmukhi":"ਨੰਦ ਕੇ ਅਗ੍ਰਜ ਕਾਨ੍ਹ ਪਰਾਕ੍ਰਮ ਗੋਪਨ ਜਾਇ ਕਹਿਯੋ ਸੁ ਸਬੈ।","roman":"Nand ke agraj kaanh paraakram gopan jaai kahiyo su sabai |","meaning_en":"","page":396},{"gurmukhi":"ਦੈਤ ਅਘਾਸੁਰ ਅਉਰ ਤ੍ਰਿਨਾਵ੍ਰਤ ਯਾਹਿ ਬਧਿਯੋ ਉਡਿ ਬੀਚ ਨਭੈ।","roman":"Dait aghaasur aur trinaavrat yaahi badhiyo udi beech nabhai |","meaning_en":"","page":396},{"gurmukhi":"ਫੁਨਿ ਮਾਰਿ ਡਰੀ ਬਕਈ ਸਭ ਗੋਪਨ ਦਾਨ ਦਯੋ ਇਹ ਕਾਨ੍ਹ ਅਭੈ।","roman":"Phuni maari daree bakaee sabh gopan daan dayo ih kaanh abhai |","meaning_en":"","page":396},{"gurmukhi":"ਸੁਨੀਐ ਪਤਿ ਕੋਟਿ ਉਪਾਵ ਕਰੋ ਕੋਊ ਪੈ ਇਹ ਸੋ ਸੁਤ ਨਾਹਿ ਨਭੈ। ੩੯੨।","roman":"Suneeai pati koti upaav karo ko'oo pai ih so sut naahi nabhai | 392 |","meaning_en":"","page":396}]},{"type":"verse","number":[393],"number_text":"੩੯੩।","page":396,"lines":[{"gurmukhi":"ਗੋਪਨ ਕੀ ਬਿਨਤੀ ਸੁਨੀਐ ਪਤਿ ਧਿਆਨ ਧਰੈ ਇਹ ਕੋ ਰਣਗਾਮੀ।","roman":"Gopan kee bintee suneeai pati dhiaan dharai ih ko rangaamee |","meaning_en":"","page":396},{"gurmukhi":"ਧਿਆਨ ਧਰੈ ਇਹ ਕੋ ਮੁਨਿ ਈਸਰ ਧਿਆਨ ਧਰੈ ਇਹ ਕਾਇਰ ਕਾਮੀ।","roman":"Dhiaan dharai ih ko muni eesar dhiaan dharai ih kaair kaamee |","meaning_en":"","page":396},{"gurmukhi":"ਧਿਆਨ ਧਰੈ ਇਹ ਕੋ ਸੁ ਤ੍ਰਿਯਾ ਸਭ ਧਿਆਨ ਧਰੈ ਇਹ ਦੇਖਨ ਬਾਮੀ।","roman":"Dhiaan dharai ih ko su triyaa sabh dhiaan dharai ih dekhan baamee |","meaning_en":"","page":396},{"gurmukhi":"ਸਤਿ ਲਖਿਯੋ ਹਮ ਕੈ ਕਰਤਾ ਜਗ ਸਤਿ ਕਹਿਯੋ ਮਤ ਕੈ ਨਹਿ ਖਾਮੀ। ੩੯੩।","roman":"Sati lakhiyo ham kai kartaa jag sati kahiyo mat kai nahi khaamee | 393 |","meaning_en":"","page":396}]},{"type":"verse","number":[394],"number_text":"੩੯੪।","page":396,"lines":[{"gurmukhi":"ਹੈ ਭਗਵਾਨ ਬਲੀ ਪ੍ਰਗਟਿਯੋ ਸਭ ਗੋਪ ਕਹੈ ਪੁਤਨਾ ਇਨ ਮਾਰੀ।","roman":"Hai bhagvaan balee pragtiyo sabh gop kahai putnaa in maaree |","meaning_en":"","page":396},{"gurmukhi":"ਰਾਜ ਬਿਭੀਛਨ ਯਾਹਿ ਦਯੋ ਇਨ ਹੀ ਕੁਪਿ ਰਾਵਨ ਦੈਤ ਸੰਘਾਰੀ।","roman":"Raaj bibheechhan yaahi dayo in hee kupi raavan dait sanghaaree |","meaning_en":"","page":396},{"gurmukhi":"ਰਛ ਕਰੀ ਪ੍ਰਲਾਦਹਿ ਕੀ ਇਨ ਹੀ ਹਰਨਾਖਸ ਕੀ ਉਰ ਫਾਰੀ।","roman":"Rachh karee pralaadhi kee in hee harnaakhas kee ur phaaree |","meaning_en":"","page":396},{"gurmukhi":"ਨੰਦ ਸੁਨੋ ਪਤਿ ਲੋਕਨ ਕੈ ਇਨ ਹੀ ਹਮਰੀ ਅਬ ਦੇਹ ਉਬਾਰੀ। ੩੯੪।","roman":"Nand suno pati lokan kai in hee hamree ab deh ubaaree | 394 |","meaning_en":"","page":396}]},{"type":"verse","number":[395],"number_text":"੩੯੫।","page":396,"lines":[{"gurmukhi":"ਹੈ ਸਭ ਲੋਗਨ ਕੋ ਕਰਤਾ ਬ੍ਰਿਜ ਭੀਤਰ ਹੈ ਕਰਤਾ ਇਹ ਲੀਲਾ।","roman":"Hai sabh logan ko kartaa brij bheetar hai kartaa ih leelaa |","meaning_en":"","page":396},{"gurmukhi":"ਸਿਖ੍ਯਨ ਕੋ ਬਰਤਾ ਹਰਿ ਹੈ ਇਹ ਸਾਧਨ ਕੋ ਹਰਤਾ ਤਨ ਹੀਲਾ।","roman":"Sikhyan ko bartaa hari hai ih saadhan ko hartaa tan heelaa |","meaning_en":"","page":396},{"gurmukhi":"ਰਾਖ ਲਈ ਇਨ ਹੀ ਸੀਅ ਕੀ ਪਤਿ ਰਾਖਿ ਲਈ ਤ੍ਰਿਯ ਪਾਰਥ ਸੀਲਾ।","roman":"Raakh laee in hee seea kee pati raakhi laee triy paarath seelaa |","meaning_en":"","page":396},{"gurmukhi":"ਗੋਪ ਕਹੈ ਪਤਿ ਸੋ ਸੁਨੀਐ ਇਹ ਹੈ ਕ੍ਰਿਸਨੰ ਬਰ ਬੀਰ ਹਠੀਲਾ। ੩੯੫।","roman":"Gop kahai pati so suneeai ih hai krisnan bar beer hatheelaa | 395 |","meaning_en":"","page":396}]},{"type":"verse","number":[396],"number_text":"੩੯੬।","page":396,"lines":[{"gurmukhi":"ਦਿਨ ਬੀਤ ਗਏ ਚਕਏ ਗਿਰਿ ਕੇ ਹਰਿ ਜੀ ਬਛਰੇ ਸੰਗ ਲੈ ਬਨਿ ਜਾਵੈ।","roman":"Din beet gae chakae giri ke hari jee bachhre sang lai bani jaavai |","meaning_en":"","page":396},{"gurmukhi":"ਜਿਉ ਧਰ ਮੂਰਤਿ ਘਾਸੁ ਚੁਗੈ ਭਗਵਾਨ ਮਹਾ ਮਨ ਮੈ ਸੁਖ ਪਾਵੈ।","roman":"Jiu dhar moorti ghaasu chugai bhagvaan mahaa man mai sukh paavai |","meaning_en":"","page":396},{"gurmukhi":"ਲੈ ਮੁਰਲੀ ਅਪੁਨੇ ਕਰ ਮੈ ਕਰਿ ਭਾਵ ਘਨੇ ਹਿਤ ਸਾਥ ਬਜਾਵੈ।","roman":"Lai murlee apune kar mai kari bhaav ghane hit saath bajaavai |","meaning_en":"","page":396},{"gurmukhi":"ਮੋਹਿ ਰਹੈ ਜੁ ਸੁਨੈ ਪਤਨੀ ਸੁਰ ਮੋਹਿ ਰਹੈ ਧੁਨਿ ਜੋ ਸੁਨਿ ਪਾਵੈ। ੩੯੬।","roman":"Mohi rahai ju sunai patnee sur mohi rahai dhuni jo suni paavai | 396 |","meaning_en":"","page":396}]},{"type":"verse","number":[397],"number_text":"੩੯੭।","page":396,"lines":[{"gurmukhi":"ਕੁਪ ਕੈ ਜਿਨਿ ਬਾਲਿ ਮਰਿਓ ਛਿਨ ਮੈ ਅਰੁ ਰਾਵਨ ਕੀ ਜਿਨਿ ਸੈਨ ਮਰੀ ਹੈ।","roman":"Kup kai jini baali mario chhin mai aru raavan kee jini sain maree hai |","meaning_en":"","page":396},{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨ ਰਾਜ ਦਯੋ ਛਿਨ ਮੈ ਜਿਹ ਕੀ ਤਿਹ ਲੰਕ ਕਰੀ ਹੈ।","roman":"Jaahi bibheechhan raaj dayo chhin mai jih kee tih lank karee hai |","meaning_en":"","page":396},{"gurmukhi":"ਮੁਰ ਮਾਰਿ ਦਯੋ ਘਟਿਕਾਨ ਕਰੀ ਰਿਪੁ ਜਾ ਸੀਅ ਕੀ ਜੀਯ ਪੀਰ ਹਰੀ ਹੈ।","roman":"Mur maari dayo ghatikaan karee ripu jaa seea kee jeey peer haree hai |","meaning_en":"","page":396},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਭਗਵਾਨ ਸੁ ਗਊਅਨ ਕੈ ਮਿਸ ਖੇਲ ਕਰੀ ਹੈ। ੩੯੭।","roman":"So brij bhoomi bikhai bhagvaan su gaooan kai mis khel karee hai | 397 |","meaning_en":"","page":396}]},{"type":"verse","number":[398],"number_text":"੩੯੮।","page":397,"lines":[{"gurmukhi":"ਜਾਹਿ ਸਹੰਸ੍ਰ ਫਨੀ ਤਨ ਊਪਰਿ ਸੋਇ ਕਰੀ ਜਲ ਭੀਤਰ ਕ੍ਰੀੜਾ।","roman":"Jaahi sahansr phanee tan oopri soi karee jal bheetar kreeraa |","meaning_en":"","page":397},{"gurmukhi":"ਜਾਹਿ ਬਿਭੀਛਨ ਰਾਜ ਦਯੋ ਅਰੁ ਜਾਹਿ ਦਈ ਕੁਪਿ ਰਾਵਨ ਪੀੜਾ।","roman":"Jaahi bibheechhan raaj dayo aru jaahi daee kupi raavan peeraa |","meaning_en":"","page":397},{"gurmukhi":"ਜਾਹਿ ਦਯੋ ਕਰ ਕੈ ਜਗ ਭੀਤਰ ਜੀਵ ਚਰਾਚਰ ਅਉ ਗਜ ਕੀੜਾ।","roman":"Jaahi dayo kar kai jag bheetar jeev charaachar au gaj keeraa |","meaning_en":"","page":397},{"gurmukhi":"ਖੇਲਤ ਸੋ ਬ੍ਰਿਜ ਭੂਮਿ ਬਿਖੈ ਜਿਨਿ ਕੀਲ ਸੁਰਾਸੁਰ ਬੀਚ ਝਗੀੜਾ। ੩੯੮।","roman":"Khelat so brij bhoomi bikhai jini keel suraasur beech jhageeraa | 398 |","meaning_en":"","page":397}]},{"type":"verse","number":[399],"number_text":"੩੯੯।","page":397,"lines":[{"gurmukhi":"ਬੀਰ ਬਡੇ ਦੁਰਜੋਧਨ ਆਦਿਕ ਜਾਹਿ ਮਰਾਇ ਡਰੇ ਰਨਿ ਛਤ੍ਰੀ।","roman":"Beer bade durjodhan aadik jaahi maraai dare rani chhatree |","meaning_en":"","page":397},{"gurmukhi":"ਜਾਹਿ ਮਰਿਯੋ ਸਿਸੁਪਾਲ ਰਿਸੈ ਕਰਿ ਰਾਜਨ ਮੈ ਕ੍ਰਿਸਨੰ ਬਰ ਅਤ੍ਰੀ।","roman":"Jaahi mariyo sisupaal risai kari raajan mai krisnan bar atree |","meaning_en":"","page":397},{"gurmukhi":"ਖੇਲਤ ਹੈ ਸੋਊ ਗਊਅਨ ਮੈ ਜੋਊ ਹੈ ਜਗ ਕੋ ਕਰਤਾ ਬਧ ਸਤ੍ਰੀ।","roman":"Khelat hai so'oo gaooan mai jo'oo hai jag ko kartaa badh satree |","meaning_en":"","page":397},{"gurmukhi":"ਆਗਿ ਸੋ ਧੂਮ੍ਰ ਲਪੇਟਤ ਜਿਉ ਫੁਨਿ ਗੋਪ ਕਹਾਵਤ ਹੈ ਇਹ ਛਤ੍ਰੀ। ੩੯੯।","roman":"Aagi so dhoomr lapetat jiu phuni gop kahaavat hai ih chhatree | 399 |","meaning_en":"","page":397}]},{"type":"verse","number":[400],"number_text":"੪੦੦।","page":397,"lines":[{"gurmukhi":"ਕਰ ਜੁਧ ਮਰੇ ਇਕਲੇ ਮਧੁ ਕੀਟਭ ਰਾਜੁ ਸਤਕ੍ਰਿਤ ਕੋ ਜਿਹ ਦੀਆ।","roman":"Kar judh mare ikle madhu keetabh raaju satkrit ko jih deeaa |","meaning_en":"","page":397},{"gurmukhi":"ਕੁੰਭਕਰਨ ਮਰਿਯੋ ਜਿਨਿ ਹੈ ਅਰੁ ਰਾਵਨ ਕੋ ਛਿਨ ਮੈ ਬਧ ਕੀਆ।","roman":"Kunbhakran mariyo jini hai aru raavan ko chhin mai badh keeaa |","meaning_en":"","page":397},{"gurmukhi":"ਰਾਜੁ ਬਿਭੀਛਨ ਦੇ ਕਰਿ ਆਨੰਦ ਅਉਧਿ ਚਲਿਯੋ ਸੰਗਿ ਲੈ ਕਰਿ ਸੀਆ।","roman":"Raaju bibheechhan de kari aanand audhi chaliyo sangi lai kari seeaa |","meaning_en":"","page":397},{"gurmukhi":"ਪਾਪਨ ਕੇ ਬਧ ਕਾਰਨ ਸੋ ਅਵਤਾਰ ਬਿਖੈ ਬ੍ਰਿਜ ਕੇ ਅਬ ਲੀਆ। ੪੦੦।","roman":"Paapan ke badh kaaran so avtaar bikhai brij ke ab leeaa | 400 |","meaning_en":"","page":397}]},{"type":"verse","number":[401],"number_text":"੪੦੧।","page":397,"lines":[{"gurmukhi":"ਜੋ ਉਪਮਾ ਹਰਿ ਕੀ ਕਰੀ ਗੋਪਨ ਤਉ ਪਤਿ ਗੋਪਨ ਬਾਤ ਕਹੀ ਹੈ।","roman":"Jo upmaa hari kee karee gopan tau pati gopan baat kahee hai |","meaning_en":"","page":397},{"gurmukhi":"ਜੋ ਇਹ ਕੋ ਬਲੁ ਆਇ ਕਹਿਯੋ ਗਰਗੈ ਹਮ ਸੋ ਸੋਊ ਬਾਤ ਸਹੀ ਹੈ।","roman":"Jo ih ko balu aai kahiyo gargai ham so so'oo baat sahee hai |","meaning_en":"","page":397},{"gurmukhi":"ਪੂਤੁ ਕਹਿਯੋ ਬਸੁਦੇਵਹਿ ਕੋ ਦਿਜ ਤਾਹਿ ਮਿਲਿਯੋ ਫੁਨਿ ਮਾਨਿ ਇਹੀ ਹੈ।","roman":"Pootu kahiyo basudevhi ko dij taahi miliyo phuni maani ihee hai |","meaning_en":"","page":397},{"gurmukhi":"ਜੋ ਇਹ ਕੋ ਫੁਨਿ ਮਾਰਨ ਆਯੋ ਸੁ ਤਾਹੀ ਕੀ ਦੇਹ ਗਈ ਨ ਰਹੀ ਹੈ। ੪੦੧।","roman":"Jo ih ko phuni maaran aayo su taahee kee deh gaee na rahee hai | 401 |","meaning_en":"","page":397}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਇੰਦ੍ਰ ਆਇ ਦਰਸਨ ਕੀਆ ਅਰੁ ਬੇਨਤੀ ਕਰਤ ਭਯਾ","gurmukhi":"ਅਥ ਇੰਦ੍ਰ ਆਇ ਦਰਸਨ ਕੀਆ ਅਰੁ ਬੇਨਤੀ ਕਰਤ ਭਯਾ","roman":"Ath indr aai darsan keeaa aru bentee karat bhayaa","meaning_en":"","page":397},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":397},{"type":"verse","number":[402],"number_text":"੪੦੨।","page":397,"lines":[{"gurmukhi":"ਦਿਨ ਏਕ ਗਏ ਬਨ ਕੋ ਹਰਿ ਜੀ ਮਘਵਾ ਤਜਿ ਮਾਨ ਹਰੀ ਪਹਿ ਆਯੋ।","roman":"Din ek gae ban ko hari jee maghvaa taji maan haree pahi aayo |","meaning_en":"","page":397},{"gurmukhi":"ਪਾਪਨ ਕੇ ਬਖਸਾਵਨ ਕੋ ਹਰਿ ਕੇ ਤਰਿ ਪਾਇਨ ਸੀਸ ਨਿਵਾਯੋ।","roman":"Paapan ke bakhsaavan ko hari ke tari paain sees nivaayo |","meaning_en":"","page":397},{"gurmukhi":"ਅਉਰ ਕਰੀ ਬਿਨਤੀ ਹਰਿ ਕੀ ਅਤਿ ਹੀ ਤਿਹ ਤੋ ਭਗਵਾਨ ਰਿਝਾਯੋ।","roman":"Aur karee bintee hari kee ati hee tih to bhagvaan rijhaayo |","meaning_en":"","page":397},{"gurmukhi":"ਚੂਕ ਭਈ ਹਮ ਤੇ ਕਹਿਯੋ ਸਕ੍ਰ ਸੁ ਕੈ ਹਰਿ ਜੀ ਤੁਮ ਕੌ ਨਹਿ ਪਾਯੋ। ੪੦੨।","roman":"Chook bhaee ham te kahiyo sakr su kai hari jee tum kau nahi paayo | 402 |","meaning_en":"","page":397}]},{"type":"verse","number":[403],"number_text":"੪੦੩।","page":397,"lines":[{"gurmukhi":"ਤੂ ਜਗ ਕੋ ਕਰਤਾ ਕਰੁਨਾਨਿਧਿ ਤੂ ਸਭ ਲੋਗਨ ਕੋ ਕਰਤਾ ਹੈ।","roman":"Too jag ko kartaa karunaanidhi too sabh logan ko kartaa hai |","meaning_en":"","page":397},{"gurmukhi":"ਤੂ ਮੁਰ ਕੋ ਮਰੀਯਾ ਰਿਪੁ ਰਾਵਨ ਭੂਰਿਸਿਲਾ ਤ੍ਰੀਯਾ ਕੋ ਭਰਤਾ ਹੈ।","roman":"Too mur ko mareeyaa ripu raavan bhoorisilaa treeyaa ko bhartaa hai |","meaning_en":"","page":397},{"gurmukhi":"ਤੂ ਸਭ ਦੇਵਨ ਕੋ ਪਤਿ ਹੈ ਅਰੁ ਸਾਧਨ ਕੇ ਦੁਖ ਕੋ ਹਰਤਾ ਹੈ।","roman":"Too sabh devan ko pati hai aru saadhan ke dukh ko hartaa hai |","meaning_en":"","page":397},{"gurmukhi":"ਜੋ ਤੁਮਰੀ ਕਛੁ ਭੂਲ ਕਰੈ ਤਿਹ ਕੇ ਫੁਨਿ ਤੂ ਤਨ ਕੋ ਮਰਤਾ ਹੈ। ੪੦੩।","roman":"Jo tumree kachhu bhool karai tih ke phuni too tan ko martaa hai | 403 |","meaning_en":"","page":397}]},{"type":"verse","number":[404],"number_text":"੪੦੪।","page":398,"lines":[{"gurmukhi":"ਸੁਨਿ ਕਾਨ੍ਹ ਸਤਕ੍ਰਿਤ ਕੀ ਉਪਮਾ ਤਬ ਕਾਮ ਸੁ ਧੇਨ ਗਊ ਚਲਿ ਆਈ।","roman":"Suni kaanh satkrit kee upmaa tab kaam su dhen gaoo chali aaee |","meaning_en":"","page":398},{"gurmukhi":"ਆਇ ਕਰੀ ਉਪਮਾ ਹਰਿ ਕੀ ਬਹੁ ਭਾਤਿਨ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਬਡਾਈ।","roman":"Aai karee upmaa hari kee bahu bhaatin so kabi syaam badaaee |","meaning_en":"","page":398},{"gurmukhi":"ਗਾਵਤ ਹੀ ਗੁਨ ਕਾਨਰ ਕੇ ਇਕ ਕਿੰਕਰ ਆਇ ਗਈ ਹਰਿ ਪਾਈ।","roman":"Gaavat hee gun kaanar ke ik kinkar aai gaee hari paaee |","meaning_en":"","page":398},{"gurmukhi":"ਸ੍ਯਾਮ ਕਰੋ ਉਪਮਾ ਕਹਿਯੋ ਪਤਿ ਸੋ ਉਪਮਾ ਬਹੁ ਭਾਤਿਨ ਭਾਈ। ੪੦੪।","roman":"Syaam karo upmaa kahiyo pati so upmaa bahu bhaatin bhaaee | 404 |","meaning_en":"","page":398}]},{"type":"verse","number":[405],"number_text":"੪੦੫।","page":398,"lines":[{"gurmukhi":"ਕਾਨਰ ਕੇ ਪਗ ਪੂਜਨ ਕੋ ਸਭ ਦੇਵਪੁਰੀ ਤਜਿ ਕੈ ਸੁਰ ਆਏ।","roman":"Kaanar ke pag poojan ko sabh devpuree taji kai sur aae |","meaning_en":"","page":398},{"gurmukhi":"ਪਾਇ ਪਰੇ ਇਕ ਪੂਜਤ ਭੇ ਇਕ ਨਾਚ ਉਠੇ ਇਕ ਮੰਗਲ ਗਾਏ।","roman":"Paai pare ik poojat bhe ik naach uthe ik mangal gaae |","meaning_en":"","page":398},{"gurmukhi":"ਸੇਵ ਕਰੈ ਹਰਿ ਕੀ ਹਿਤ ਕੈ ਕਰਿ ਆਵਤ ਕੇਸਰ ਧੂਪ ਜਗਾਏ।","roman":"Sev karai hari kee hit kai kari aavat kesar dhoop jagaae |","meaning_en":"","page":398},{"gurmukhi":"ਦੈਤਨ ਕੋ ਬਧ ਕੈ ਭਗਵਾਨ ਮਨੋ ਜਗ ਮੈ ਸੁਰ ਫੇਰਿ ਬਸਾਏ। ੪੦੫।","roman":"Daitan ko badh kai bhagvaan mano jag mai sur pheri basaae | 405 |","meaning_en":"","page":398}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":398},{"type":"verse","number":[406],"number_text":"੪੦੬।","page":398,"lines":[{"gurmukhi":"ਦੇਵ ਸਕ੍ਰ ਆਦਿਕ ਸਭੈ ਸਭ ਤਜਿ ਕੈ ਮਨਿ ਮਾਨ।","roman":"Dev sakr aadik sabhai sabh taji kai mani maan |","meaning_en":"","page":398},{"gurmukhi":"ਹ੍ਵੈ ਇਕਤ੍ਰ ਕਰਨੈ ਲਗੇ ਕ੍ਰਿਸਨ ਉਸਤਤੀ ਬਾਨਿ। ੪੦੬।","roman":"Hvai ikatr karnai lage krisan usattee baani | 406 |","meaning_en":"","page":398}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":398},{"type":"verse","number":[407],"number_text":"੪੦੭।","page":398,"lines":[{"gurmukhi":"ਪ੍ਰੇਮ ਭਰੇ ਲਾਜ ਕੇ ਜਹਾਜ ਦੋਊ ਦੇਖੀਅਤ ਬਾਰਿ ਭਰੇ ਅਭ੍ਰਨ ਕੀ ਆਭਾ ਕੋ ਧਰਤ ਹੈ।","roman":"Prem bhare laaj ke jahaaj do'oo dekheeat baari bhare abhran kee aabhaa ko dharat hai |","meaning_en":"","page":398},{"gurmukhi":"ਸੀਲ ਕੇ ਹੈ ਸਿੰਧੁ ਗੁਨ ਸਾਗਰ ਉਜਾਗਰ ਕੇ ਨਾਗਰ ਨਵਲ ਨੈਨ ਦੋਖਨ ਹਰਤ ਹੈ।","roman":"Seel ke hai sindhu gun saagar ujaagar ke naagar naval nain dokhan harat hai |","meaning_en":"","page":398},{"gurmukhi":"ਸਤ੍ਰਨ ਸੰਘਾਰੀ ਇਹ ਕਾਨ੍ਹ ਅਵਤਾਰੀ ਜੂ ਕੇ ਸਾਧਨ ਕੋ ਦੇਹ ਦੂਖ ਦੂਰ ਕੋ ਕਰਤ ਹੈ।","roman":"Satran sanghaaree ih kaanh avtaaree joo ke saadhan ko deh dookh door ko karat hai |","meaning_en":"","page":398},{"gurmukhi":"ਮਿਤ੍ਰ ਪ੍ਰਿਤਿਪਾਰਕ ਏ ਜਗ ਕੇ ਉਧਾਰਕ ਹੈ ਦੇਖ ਕੈ ਦੁਸਟ ਜਿਹ ਜੀਯ ਤੇ ਜਰਤ ਹੈ। ੪੦੭।","roman":"Mitr pritipaarak e jag ke udhaarak hai dekh kai dusat jih jeey te jarat hai | 407 |","meaning_en":"","page":398}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":398},{"type":"verse","number":[408],"number_text":"੪੦੮।","page":398,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਸੀਸ ਨਿਵਾਇ ਸਭੈ ਸੁਰ ਆਇਸੁ ਲੈ ਚਲ ਧਾਮਿ ਗਏ ਹੈ।","roman":"Kaanh ko sees nivaai sabhai sur aaisu lai chal dhaami gae hai |","meaning_en":"","page":398},{"gurmukhi":"ਗੋਬਿੰਦ ਨਾਮ ਧਰਿਯੋ ਹਰਿ ਕੋ ਇਹ ਤੈ ਮਨ ਆਨੰਦ ਯਾਦ ਭਏ ਹੈ।","roman":"Gobind naam dhariyo hari ko ih tai man aanand yaad bhae hai |","meaning_en":"","page":398},{"gurmukhi":"ਰਾਤਿ ਪਰੇ ਚਲਿ ਕੈ ਭਗਵਾਨ ਸੁ ਡੇਰਨਿ ਆਪਨ ਬੀਚ ਅਏ ਹੈ।","roman":"Raati pare chali kai bhagvaan su derni aapan beech ae hai |","meaning_en":"","page":398},{"gurmukhi":"ਪ੍ਰਾਤਿ ਭਏ ਜਗ ਕੇ ਦਿਖਬੇ ਕਹੁ ਕੀਨ ਸੁ ਸੁੰਦਰ ਖੇਲ ਨਏ ਹੈ। ੪੦੮।","roman":"Praati bhae jag ke dikhbe kahu keen su sundar khel nae hai | 408 |","meaning_en":"","page":398}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸ਼ਨਾਵਤਾਰੇ ਇੰਦ੍ਰ ਭੂਲ ਬਖਸਾਵਨ","roman":"Iti sree bachitr naatak granthe krishnaavtaare indr bhool bakhsaavan","meaning_en":"","page":398},{"gurmukhi":"ਨਾਮ ਬਰਨਨੰ ਧਿਆਇ ਸਮਾਪਤਮ।","roman":"Naam barannan dhiaai samaaptam |","meaning_en":"","page":398}],"page":398}});
